// Comprehensive D&D 5e SRD Spell Database
// Organized by spell level with class availability and metadata

window.SPELL_DATABASE = {
  // Cantrips (Level 0)
  0: [
    { id: 'acid-splash', name: 'Acid Splash', school: 'Conjuration', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Hurl a bubble of acid at one or two creatures within 5 feet of each other. Each must succeed on a Dex save or take 1d6 acid damage. Scales at 5th (2d6), 11th (3d6), 17th (4d6).', tags: ['damage', 'acid'] },
    { id: 'blade-ward', name: 'Blade Ward', school: 'Abjuration', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '1 round', description: 'Gain resistance to bludgeoning, piercing, and slashing damage from weapon attacks until end of next turn.', tags: ['defense', 'protection'] },
    { id: 'chill-touch', name: 'Chill Touch', school: 'Necromancy', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: '1 round', description: 'Ghostly skeletal hand deals 1d8 necrotic damage and prevents healing until your next turn. Undead also have disadvantage against you. Scales at 5th, 11th, 17th.', tags: ['damage', 'necrotic', 'debuff'] },
    { id: 'dancing-lights', name: 'Dancing Lights', school: 'Evocation', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create up to four torch-sized lights or one glowing humanoid form. Move them up to 60 feet as a bonus action.', tags: ['utility', 'light'] },
    { id: 'druidcraft', name: 'Druidcraft', school: 'Transmutation', classes: ['druid'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: 'Instantaneous', description: 'Create a tiny harmless sensory effect, light or snuff a small flame, predict weather, or make a plant bloom.', tags: ['utility', 'nature'] },
    { id: 'eldritch-blast', name: 'Eldritch Blast', school: 'Evocation', classes: ['warlock'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Instantaneous', description: 'Beam of crackling energy deals 1d10 force damage. Additional beams at 5th (2), 11th (3), 17th (4).', tags: ['damage', 'force'] },
    { id: 'fire-bolt', name: 'Fire Bolt', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Instantaneous', description: 'Hurl a mote of fire at a creature or object. 1d10 fire damage on hit. Ignites flammable objects. Scales at 5th, 11th, 17th.', tags: ['damage', 'fire'] },
    { id: 'friends', name: 'Friends', school: 'Enchantment', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Self', components: 'S, M', duration: 'Concentration, 1 minute', description: 'Gain advantage on Charisma checks against one creature. When spell ends, creature realizes it was charmed.', tags: ['social', 'charm'] },
    { id: 'guidance', name: 'Guidance', school: 'Divination', classes: ['cleric', 'druid'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Touch a willing creature. Once before the spell ends, they can add 1d4 to one ability check.', tags: ['buff', 'support'] },
    { id: 'light', name: 'Light', school: 'Evocation', classes: ['bard', 'cleric', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, M', duration: '1 hour', description: 'Touch an object no larger than 10 feet. It sheds bright light in 20-foot radius and dim light for additional 20 feet.', tags: ['utility', 'light'] },
    { id: 'mage-hand', name: 'Mage Hand', school: 'Conjuration', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: '1 minute', description: 'Create a spectral floating hand that can manipulate objects, open doors, or retrieve items up to 10 pounds.', tags: ['utility', 'manipulation'] },
    { id: 'mending', name: 'Mending', school: 'Transmutation', classes: ['bard', 'cleric', 'druid', 'sorcerer', 'wizard'], castingTime: '1 minute', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Repair a single break or tear in an object you touch, such as a broken chain link or torn cloak.', tags: ['utility', 'repair'] },
    { id: 'message', name: 'Message', school: 'Transmutation', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: '1 round', description: 'Whisper a message to a creature within range. Only the target hears it and can reply in a whisper.', tags: ['utility', 'communication'] },
    { id: 'minor-illusion', name: 'Minor Illusion', school: 'Illusion', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'S, M', duration: '1 minute', description: 'Create a sound or image of an object no larger than a 5-foot cube. Investigation check to determine illusion.', tags: ['utility', 'illusion', 'deception'] },
    { id: 'poison-spray', name: 'Poison Spray', school: 'Conjuration', classes: ['druid', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '10 feet', components: 'V, S', duration: 'Instantaneous', description: 'Project a puff of noxious gas. Target must succeed Con save or take 1d12 poison damage. Scales at 5th, 11th, 17th.', tags: ['damage', 'poison'] },
    { id: 'prestidigitation', name: 'Prestidigitation', school: 'Transmutation', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '10 feet', components: 'V, S', duration: 'Up to 1 hour', description: 'Create minor magical tricks: harmless sensory effect, light or snuff candle, clean or soil object, warm or chill material, make mark or symbol.', tags: ['utility', 'social'] },
    { id: 'produce-flame', name: 'Produce Flame', school: 'Conjuration', classes: ['druid'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '10 minutes', description: 'Flickering flame appears in your hand for light or to throw. Ranged spell attack deals 1d8 fire damage. Scales at 5th, 11th, 17th.', tags: ['damage', 'fire', 'utility', 'light'] },
    { id: 'ray-of-frost', name: 'Ray of Frost', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Frigid beam of blue-white light deals 1d8 cold damage and reduces speed by 10 feet until your next turn. Scales at 5th, 11th, 17th.', tags: ['damage', 'cold', 'control'] },
    { id: 'resistance', name: 'Resistance', school: 'Abjuration', classes: ['cleric', 'druid'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Touch a willing creature. Once before spell ends, they can add 1d4 to one saving throw.', tags: ['buff', 'support', 'defense'] },
    { id: 'sacred-flame', name: 'Sacred Flame', school: 'Evocation', classes: ['cleric'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Flame-like radiance descends on target. Dex save or take 1d8 radiant damage. No benefit from cover. Scales at 5th, 11th, 17th.', tags: ['damage', 'radiant'] },
    { id: 'shillelagh', name: 'Shillelagh', school: 'Transmutation', classes: ['druid'], castingTime: '1 bonus action', range: 'Touch', components: 'V, S, M', duration: '1 minute', description: 'Club or quarterstaff becomes magical, uses spellcasting ability for attack/damage, and deals 1d8 damage.', tags: ['buff', 'combat'] },
    { id: 'shocking-grasp', name: 'Shocking Grasp', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instantaneous', description: 'Lightning springs from your hand. Melee spell attack deals 1d8 lightning damage, target can\'t take reactions. Advantage vs metal armor. Scales at 5th, 11th, 17th.', tags: ['damage', 'lightning'] },
    { id: 'spare-the-dying', name: 'Spare the Dying', school: 'Necromancy', classes: ['cleric'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instantaneous', description: 'Touch a living creature at 0 hit points. It becomes stable.', tags: ['healing', 'support'] },
    { id: 'thaumaturgy', name: 'Thaumaturgy', school: 'Transmutation', classes: ['cleric'], castingTime: '1 action', range: '30 feet', components: 'V', duration: 'Up to 1 minute', description: 'Manifest minor wonder: boom your voice, flicker flames, cause tremors, create sounds, swing doors, or alter eye appearance.', tags: ['utility', 'social'] },
    { id: 'thorn-whip', name: 'Thorn Whip', school: 'Transmutation', classes: ['druid'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Create a vine-like whip. Melee spell attack deals 1d6 piercing and pulls Large or smaller creature 10 feet closer. Scales at 5th, 11th, 17th.', tags: ['damage', 'control'] },
    { id: 'toll-the-dead', name: 'Toll the Dead', school: 'Necromancy', classes: ['cleric', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Point at creature, dolorous bell tolls. Wis save or take 1d8 necrotic (1d12 if missing HP). Scales at 5th, 11th, 17th.', tags: ['damage', 'necrotic'] },
    { id: 'true-strike', name: 'True Strike', school: 'Divination', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'S', duration: 'Concentration, 1 round', description: 'Gain advantage on your first attack roll against the target on your next turn.', tags: ['buff', 'combat'] },
    { id: 'vicious-mockery', name: 'Vicious Mockery', school: 'Enchantment', classes: ['bard'], castingTime: '1 action', range: '60 feet', components: 'V', duration: 'Instantaneous', description: 'Unleash a string of insults. Wis save or take 1d4 psychic damage and have disadvantage on next attack. Scales at 5th, 11th, 17th.', tags: ['damage', 'psychic', 'debuff', 'social'] },
    { id: 'word-of-radiance', name: 'Word of Radiance', school: 'Evocation', classes: ['cleric'], castingTime: '1 action', range: '5 feet', components: 'V, M', duration: 'Instantaneous', description: 'Speak a divine word. Each creature of choice within range must make Con save or take 1d6 radiant damage. Scales at 5th, 11th, 17th.', tags: ['damage', 'radiant', 'aoe'] },
  ],

  // 1st Level Spells
  1: [
    { id: 'alarm', name: 'Alarm', school: 'Abjuration', classes: ['ranger', 'wizard'], castingTime: '1 minute', range: '30 feet', components: 'V, S, M', duration: '8 hours', description: 'Set a ward on a 20-foot cube. Alerts you (mental or audible) when a creature enters without speaking a password.', tags: ['utility', 'detection', 'ritual'] },
    { id: 'animal-friendship', name: 'Animal Friendship', school: 'Enchantment', classes: ['bard', 'druid', 'ranger'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: '24 hours', description: 'Charm a beast with Intelligence 3 or lower for 24 hours. Wis save negates.', tags: ['charm', 'nature'] },
    { id: 'armor-of-agathys', name: 'Armor of Agathys', school: 'Abjuration', classes: ['warlock'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '1 hour', description: 'Gain 5 temp HP. While you have these HP, creature that hits you with melee attack takes 5 cold damage. Upcast: +5 temp HP and damage per slot level.', tags: ['defense', 'cold', 'retaliation'] },
    { id: 'arms-of-hadar', name: 'Arms of Hadar', school: 'Conjuration', classes: ['warlock'], castingTime: '1 action', range: 'Self (10-foot radius)', components: 'V, S', duration: 'Instantaneous', description: 'Tendrils of dark energy erupt from you. Each creature in 10-foot radius makes Str save or takes 2d6 necrotic and can\'t take reactions. Upcast: +1d6 per slot level.', tags: ['damage', 'necrotic', 'aoe'] },
    { id: 'bane', name: 'Bane', school: 'Enchantment', classes: ['bard', 'cleric'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Up to 3 creatures must make Cha save or subtract 1d4 from attack rolls and saves. Upcast: +1 target per slot level.', tags: ['debuff', 'control'] },
    { id: 'bless', name: 'Bless', school: 'Enchantment', classes: ['cleric', 'paladin'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Up to 3 creatures add 1d4 to attack rolls and saving throws. Upcast: +1 target per slot level.', tags: ['buff', 'support'] },
    { id: 'burning-hands', name: 'Burning Hands', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self (15-foot cone)', components: 'V, S', duration: 'Instantaneous', description: 'Thin sheet of flames shoots from your fingertips. Each creature in 15-foot cone makes Dex save, taking 3d6 fire damage (half on save). Upcast: +1d6 per slot level.', tags: ['damage', 'fire', 'aoe'] },
    { id: 'charm-person', name: 'Charm Person', school: 'Enchantment', classes: ['bard', 'druid', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: '1 hour', description: 'Charm a humanoid you can see. Wis save (advantage if fighting you). Charmed creature regards you as friendly. Knows it was charmed when spell ends.', tags: ['charm', 'social'] },
    { id: 'chromatic-orb', name: 'Chromatic Orb', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '90 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Hurl a 4-inch sphere of energy. Choose acid, cold, fire, lightning, poison, or thunder. Ranged spell attack deals 3d8 damage of chosen type. Upcast: +1d8 per slot level.', tags: ['damage', 'versatile'] },
    { id: 'color-spray', name: 'Color Spray', school: 'Illusion', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self (15-foot cone)', components: 'V, S, M', duration: '1 round', description: 'Dazzling array of flashing colors springs from your hand. Roll 6d10; creatures in cone are blinded starting from lowest HP until the roll is exceeded. Upcast: +2d10 per slot level.', tags: ['control', 'debuff'] },
    { id: 'command', name: 'Command', school: 'Enchantment', classes: ['cleric', 'paladin'], castingTime: '1 action', range: '60 feet', components: 'V', duration: 'Instantaneous', description: 'Speak a one-word command (Approach, Drop, Flee, Grovel, Halt). Wis save or follow command on next turn. No effect on undead or if command is directly harmful.', tags: ['control', 'debuff'] },
    { id: 'compelled-duel', name: 'Compelled Duel', school: 'Enchantment', classes: ['paladin'], castingTime: '1 bonus action', range: '30 feet', components: 'V', duration: 'Concentration, 1 minute', description: 'Compel a creature to duel you. Wis save or disadvantage on attacks against others and can\'t willingly move more than 30 feet from you.', tags: ['control', 'combat'] },
    { id: 'comprehend-languages', name: 'Comprehend Languages', school: 'Divination', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '1 hour', description: 'Understand the literal meaning of any spoken language you hear and written language you touch (1 minute per page).', tags: ['utility', 'communication', 'ritual'] },
    { id: 'create-or-destroy-water', name: 'Create or Destroy Water', school: 'Transmutation', classes: ['cleric', 'druid'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Create up to 10 gallons of clean water or destroy up to 10 gallons of water in a 30-foot cube. Upcast: +10 gallons per slot level.', tags: ['utility'] },
    { id: 'cure-wounds', name: 'Cure Wounds', school: 'Evocation', classes: ['bard', 'cleric', 'druid', 'paladin', 'ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instantaneous', description: 'Creature you touch regains 1d8 + spellcasting modifier HP. No effect on undead or constructs. Upcast: +1d8 per slot level.', tags: ['healing'] },
    { id: 'detect-evil-and-good', name: 'Detect Evil and Good', school: 'Divination', classes: ['cleric', 'paladin'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Know if aberration, celestial, elemental, fey, fiend, or undead is within 30 feet, and where it is.', tags: ['detection', 'utility'] },
    { id: 'detect-magic', name: 'Detect Magic', school: 'Divination', classes: ['bard', 'cleric', 'druid', 'paladin', 'ranger', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Sense the presence of magic within 30 feet. See a faint aura around any visible creature or object that bears magic and learn its school.', tags: ['detection', 'utility', 'ritual'] },
    { id: 'detect-poison-and-disease', name: 'Detect Poison and Disease', school: 'Divination', classes: ['cleric', 'druid', 'paladin', 'ranger'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet.', tags: ['detection', 'utility', 'ritual'] },
    { id: 'disguise-self', name: 'Disguise Self', school: 'Illusion', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '1 hour', description: 'Make yourself look different. Change height by up to 1 foot, appear thinner/fatter/in between. Can\'t change body type. Investigation check sees through it.', tags: ['illusion', 'utility', 'social'] },
    { id: 'dissonant-whispers', name: 'Dissonant Whispers', school: 'Enchantment', classes: ['bard'], castingTime: '1 action', range: '60 feet', components: 'V', duration: 'Instantaneous', description: 'Whisper a discordant melody only one creature can hear. Wis save or take 3d6 psychic damage and immediately use reaction to move away. Upcast: +1d6 per slot level.', tags: ['damage', 'psychic', 'control'] },
    { id: 'divine-favor', name: 'Divine Favor', school: 'Evocation', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Your weapon is imbued with divine energy. Until spell ends, weapon attacks deal extra 1d4 radiant damage.', tags: ['buff', 'combat', 'radiant'] },
    { id: 'entangle', name: 'Entangle', school: 'Conjuration', classes: ['druid'], castingTime: '1 action', range: '90 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Grasping weeds and vines sprout in 20-foot square. Creatures in area must make Str save or be restrained. Area is difficult terrain.', tags: ['control', 'terrain'] },
    { id: 'expeditious-retreat', name: 'Expeditious Retreat', school: 'Transmutation', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 bonus action', range: 'Self', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Take the Dash action as a bonus action on each of your turns until the spell ends.', tags: ['buff', 'mobility'] },
    { id: 'faerie-fire', name: 'Faerie Fire', school: 'Evocation', classes: ['bard', 'druid'], castingTime: '1 action', range: '60 feet', components: 'V', duration: 'Concentration, 1 minute', description: 'Objects in 20-foot cube are outlined in light. Creatures that fail Dex save are also outlined. Affected creatures/objects shed dim light and can\'t benefit from invisibility. Attacks against them have advantage.', tags: ['buff', 'support', 'debuff'] },
    { id: 'false-life', name: 'False Life', school: 'Necromancy', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '1 hour', description: 'Bolster yourself with a necromantic facsimile of life, gaining 1d4 + 4 temporary hit points. Upcast: +5 temp HP per slot level above 1st.', tags: ['defense', 'buff'] },
    { id: 'feather-fall', name: 'Feather Fall', school: 'Transmutation', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 reaction', range: '60 feet', components: 'V, M', duration: '1 minute', description: 'Choose up to 5 falling creatures. A falling creature\'s rate of descent slows to 60 feet per round and takes no falling damage.', tags: ['utility', 'protection'] },
    { id: 'find-familiar', name: 'Find Familiar', school: 'Conjuration', classes: ['wizard'], castingTime: '1 hour', range: '10 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Gain a spirit familiar in animal form (bat, cat, crab, frog, hawk, lizard, octopus, owl, poisonous snake, fish, rat, raven, sea horse, spider, or weasel). Can telepathically communicate, see through its eyes, deliver touch spells through it.', tags: ['utility', 'summoning', 'ritual'] },
    { id: 'fog-cloud', name: 'Fog Cloud', school: 'Conjuration', classes: ['druid', 'ranger', 'sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Create a 20-foot-radius sphere of fog centered on a point. Area is heavily obscured. Upcast: radius increases by 20 feet per slot level.', tags: ['control', 'terrain'] },
    { id: 'goodberry', name: 'Goodberry', school: 'Transmutation', classes: ['druid', 'ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Create up to 10 berries infused with magic. Eating a berry restores 1 HP and provides enough nourishment for one day.', tags: ['healing', 'utility'] },
    { id: 'grease', name: 'Grease', school: 'Conjuration', classes: ['wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: '1 minute', description: 'Slick grease covers ground in 10-foot square. Creatures entering or starting turn there must make Dex save or fall prone. Area is difficult terrain.', tags: ['control', 'terrain'] },
    { id: 'guiding-bolt', name: 'Guiding Bolt', school: 'Evocation', classes: ['cleric'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: '1 round', description: 'Flash of light streaks toward a creature. Ranged spell attack deals 4d6 radiant damage and grants advantage on next attack against target. Upcast: +1d6 per slot level.', tags: ['damage', 'radiant', 'buff'] },
    { id: 'hail-of-thorns', name: 'Hail of Thorns', school: 'Conjuration', classes: ['ranger'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Next time you hit with ranged weapon attack, thorns erupt. Target and creatures within 5 feet make Dex save, taking 1d10 piercing (half on save). Upcast: +1d10 per slot level.', tags: ['damage', 'aoe'] },
    { id: 'healing-word', name: 'Healing Word', school: 'Evocation', classes: ['bard', 'cleric', 'druid'], castingTime: '1 bonus action', range: '60 feet', components: 'V', duration: 'Instantaneous', description: 'Creature you can see regains 1d4 + spellcasting modifier HP. No effect on undead or constructs. Upcast: +1d4 per slot level.', tags: ['healing', 'bonus-action'] },
    { id: 'hellish-rebuke', name: 'Hellish Rebuke', school: 'Evocation', classes: ['warlock'], castingTime: '1 reaction', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Point at creature that damaged you. It must make Dex save, taking 2d10 fire damage on fail, half on success. Upcast: +1d10 per slot level.', tags: ['damage', 'fire', 'reaction', 'retaliation'] },
    { id: 'heroism', name: 'Heroism', school: 'Enchantment', classes: ['bard', 'paladin'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Creature is immune to being frightened and gains temp HP equal to your spellcasting modifier at start of each turn. Upcast: +1 target per slot level.', tags: ['buff', 'support'] },
    { id: 'hex', name: 'Hex', school: 'Enchantment', classes: ['warlock'], castingTime: '1 bonus action', range: '90 feet', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Curse a creature. Your attacks deal extra 1d6 necrotic damage and it has disadvantage on ability checks with one chosen ability. Move curse to new creature if target drops to 0 HP. Upcast: duration increases.', tags: ['damage', 'necrotic', 'debuff', 'curse'] },
    { id: 'hunters-mark', name: "Hunter's Mark", school: 'Divination', classes: ['ranger'], castingTime: '1 bonus action', range: '90 feet', components: 'V', duration: 'Concentration, 1 hour', description: 'Mark a creature as quarry. Deal extra 1d6 damage with weapon attacks against it and have advantage on Perception and Survival checks to find it. Move mark to new creature if target drops to 0 HP. Upcast: duration increases.', tags: ['damage', 'buff', 'tracking'] },
    { id: 'identify', name: 'Identify', school: 'Divination', classes: ['bard', 'wizard'], castingTime: '1 minute', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Learn the properties of a magic item, whether it requires attunement, how many charges it has, and any spells affecting it.', tags: ['utility', 'knowledge', 'ritual'] },
    { id: 'illusory-script', name: 'Illusory Script', school: 'Illusion', classes: ['bard', 'warlock', 'wizard'], castingTime: '1 minute', range: 'Touch', components: 'S, M', duration: '10 days', description: 'Write on parchment that appears normal or different to those you designate. True message visible only to you and designated creatures.', tags: ['utility', 'illusion', 'ritual'] },
    { id: 'inflict-wounds', name: 'Inflict Wounds', school: 'Necromancy', classes: ['cleric'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instantaneous', description: 'Make a melee spell attack. On hit, target takes 3d10 necrotic damage. Upcast: +1d10 per slot level.', tags: ['damage', 'necrotic'] },
    { id: 'jump', name: 'Jump', school: 'Transmutation', classes: ['druid', 'ranger', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 minute', description: 'Touch a creature. Its jump distance is tripled until the spell ends.', tags: ['buff', 'mobility'] },
    { id: 'longstrider', name: 'Longstrider', school: 'Transmutation', classes: ['bard', 'druid', 'ranger', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', description: "Touch a creature. Its speed increases by 10 feet until the spell ends. Upcast: +1 target per slot level.", tags: ['buff', 'mobility'] },
    { id: 'mage-armor', name: 'Mage Armor', school: 'Abjuration', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '8 hours', description: "Touch a willing creature who isn't wearing armor. Its base AC becomes 13 + its Dexterity modifier. Spell ends if target dons armor.", tags: ['defense', 'buff'] },
    { id: 'magic-missile', name: 'Magic Missile', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Instantaneous', description: 'Create 3 glowing darts of magical force. Each dart hits automatically and deals 1d4+1 force damage. Can target one creature or several. Upcast: +1 dart per slot level.', tags: ['damage', 'force', 'reliable'] },
    { id: 'protection-from-evil-and-good', name: 'Protection from Evil and Good', school: 'Abjuration', classes: ['cleric', 'paladin', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Aberrations, celestials, elementals, fey, fiends, and undead have disadvantage on attacks against target. Target can\'t be charmed, frightened, or possessed by them.', tags: ['defense', 'protection'] },
    { id: 'purify-food-and-drink', name: 'Purify Food and Drink', school: 'Transmutation', classes: ['cleric', 'druid', 'paladin'], castingTime: '1 action', range: '10 feet', components: 'V, S', duration: 'Instantaneous', description: 'All nonmagical food and drink within 5-foot-radius sphere is purified and rendered free of poison and disease.', tags: ['utility', 'ritual'] },
    { id: 'sanctuary', name: 'Sanctuary', school: 'Abjuration', classes: ['cleric'], castingTime: '1 bonus action', range: '30 feet', components: 'V, S, M', duration: '1 minute', description: 'Ward a creature. Any creature targeting warded creature with attack or harmful spell must make Wis save. On fail, must choose new target or lose the attack/spell. Ends if warded creature attacks or casts harmful spell.', tags: ['defense', 'protection'] },
    { id: 'searing-smite', name: 'Searing Smite', school: 'Evocation', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Next melee weapon hit deals extra 1d6 fire damage and ignites target. Target takes 1d6 fire damage at start of each turn until it or creature uses action to extinguish. Upcast: +1d6 initial damage per slot level.', tags: ['damage', 'fire', 'combat'] },
    { id: 'shield', name: 'Shield', school: 'Abjuration', classes: ['sorcerer', 'wizard'], castingTime: '1 reaction', range: 'Self', components: 'V, S', duration: '1 round', description: 'An invisible barrier of magical force appears and protects you. Until start of your next turn, you have +5 bonus to AC, including against triggering attack, and take no damage from magic missile.', tags: ['defense', 'reaction'] },
    { id: 'shield-of-faith', name: 'Shield of Faith', school: 'Abjuration', classes: ['cleric', 'paladin'], castingTime: '1 bonus action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'A shimmering field appears around a creature, granting +2 bonus to AC for the duration.', tags: ['defense', 'buff'] },
    { id: 'silent-image', name: 'Silent Image', school: 'Illusion', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Create the image of an object, creature, or phenomenon that fits within a 15-foot cube. It can seem to move but makes no sound. Investigation check to determine illusion.', tags: ['illusion', 'utility'] },
    { id: 'sleep', name: 'Sleep', school: 'Enchantment', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '90 feet', components: 'V, S, M', duration: '1 minute', description: 'Roll 5d8; creatures within 20-foot radius fall unconscious starting from lowest HP until roll is exceeded. Undead and immune to charmed creatures unaffected. Upcast: +2d8 per slot level.', tags: ['control', 'debuff'] },
    { id: 'speak-with-animals', name: 'Speak with Animals', school: 'Divination', classes: ['bard', 'druid', 'ranger'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '10 minutes', description: 'Gain the ability to comprehend and verbally communicate with beasts. Knowledge and awareness are limited by intelligence.', tags: ['utility', 'communication', 'ritual'] },
    { id: 'tashas-hideous-laughter', name: "Tasha's Hideous Laughter", school: 'Enchantment', classes: ['bard', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Creature must succeed Wis save or fall prone, becoming incapacitated and unable to stand. Repeats save at end of each turn and when it takes damage.', tags: ['control', 'debuff'] },
    { id: 'thunderous-smite', name: 'Thunderous Smite', school: 'Evocation', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Next melee weapon hit deals extra 2d6 thunder damage and target must succeed Str save or be pushed 10 feet and knocked prone.', tags: ['damage', 'thunder', 'control'] },
    { id: 'thunderwave', name: 'Thunderwave', school: 'Evocation', classes: ['bard', 'druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Self (15-foot cube)', components: 'V, S', duration: 'Instantaneous', description: 'Wave of thunderous force sweeps out. Creatures in 15-foot cube make Con save, taking 2d8 thunder damage and pushed 10 feet away on fail (half damage, no push on success). Unsecured objects pushed automatically. Upcast: +1d8 per slot level.', tags: ['damage', 'thunder', 'aoe', 'control'] },
    { id: 'unseen-servant', name: 'Unseen Servant', school: 'Conjuration', classes: ['bard', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: '1 hour', description: 'Create an invisible, mindless, shapeless force that performs simple tasks at your command. Has AC 10, 1 HP, Str 2.', tags: ['utility', 'summoning', 'ritual'] },
    { id: 'witch-bolt', name: 'Witch Bolt', school: 'Evocation', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Arc of lightning connects you to target. Ranged spell attack deals 1d12 lightning damage. On subsequent turns, use action to deal 1d12 automatically while maintaining concentration. Upcast: +1d12 initial damage per slot level.', tags: ['damage', 'lightning'] },
    { id: 'wrathful-smite', name: 'Wrathful Smite', school: 'Evocation', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Next melee weapon hit deals extra 1d6 psychic damage and target must make Wis save or be frightened until spell ends. Can use action to make Wis check to end fear.', tags: ['damage', 'psychic', 'debuff', 'fear'] },
  ],

  // 2nd Level Spells
  2: [
    { id: 'aid', name: 'Aid', school: 'Abjuration', classes: ['cleric', 'paladin'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: '8 hours', description: 'Bolster up to 3 creatures with toughness. Each target\'s HP max and current HP increase by 5 for the duration. Upcast: +5 per slot level above 2nd.', tags: ['buff', 'healing'] },
    { id: 'alter-self', name: 'Alter Self', school: 'Transmutation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Assume a different form: Aquatic Adaptation (swim speed, water breathing), Change Appearance (change physical characteristics), or Natural Weapons (natural weapon dealing 1d6+Str/Dex slashing, +1 attack bonus, magical).', tags: ['utility', 'transformation'] },
    { id: 'animal-messenger', name: 'Animal Messenger', school: 'Enchantment', classes: ['bard', 'druid', 'ranger'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: '24 hours', description: 'Tiny beast delivers a message up to 25 words to a specific location and recipient you describe. Beast travels 50 miles per 24 hours (flying) or 25 miles (others). Upcast: duration doubles per slot level above 2nd.', tags: ['utility', 'communication', 'ritual'] },
    { id: 'barkskin', name: 'Barkskin', school: 'Transmutation', classes: ['druid', 'ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Touch a willing creature. Its skin becomes bark-like and its AC can\'t be less than 16, regardless of armor.', tags: ['defense', 'buff'] },
    { id: 'blindness-deafness', name: 'Blindness/Deafness', school: 'Necromancy', classes: ['bard', 'cleric', 'sorcerer', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V', duration: '1 minute', description: 'Blind or deafen a creature. Con save negates. Target can repeat save at end of each turn. Upcast: +1 target per slot level above 2nd.', tags: ['debuff', 'control'] },
    { id: 'blur', name: 'Blur', school: 'Illusion', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Your body becomes blurred, shifting and wavering. Creatures have disadvantage on attack rolls against you. Creatures with blindsight or truesight or that don\'t rely on sight are unaffected.', tags: ['defense', 'illusion'] },
    { id: 'branding-smite', name: 'Branding Smite', school: 'Evocation', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Next weapon hit deals extra 2d6 radiant damage and target becomes visible (sheds dim light 5 ft) and can\'t become invisible while spell lasts. Upcast: +1d6 per slot level above 2nd.', tags: ['damage', 'radiant', 'combat'] },
    { id: 'calm-emotions', name: 'Calm Emotions', school: 'Enchantment', classes: ['bard', 'cleric'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Humanoids in 20-foot sphere make Cha save or be calmed. Choose: suppress charm/fright effects, or make hostile creatures indifferent (no longer hostile unless threatened or harmed).', tags: ['control', 'social'] },
    { id: 'continual-flame', name: 'Continual Flame', school: 'Evocation', classes: ['cleric', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Until dispelled', description: 'Create a heatless flame equivalent to a torch on an object. The flame can be covered but not smothered or quenched.', tags: ['utility', 'light'] },
    { id: 'darkness', name: 'Darkness', school: 'Evocation', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, M', duration: 'Concentration, 10 minutes', description: 'Create magical darkness in 15-foot radius sphere. Darkvision can\'t see through it. If cast on object, can be covered to block darkness. Light spells of 2nd level or lower are dispelled by it.', tags: ['control', 'terrain'] },
    { id: 'darkvision', name: 'Darkvision', school: 'Transmutation', classes: ['druid', 'ranger', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '8 hours', description: 'Grant a willing creature darkvision out to 60 feet for the duration.', tags: ['buff', 'utility'] },
    { id: 'detect-thoughts', name: 'Detect Thoughts', school: 'Divination', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Sense presence of thinking creatures within 30 feet. Focus on one to read surface thoughts. Probe deeper with opposed Int check. Target knows if it succeeds on save.', tags: ['detection', 'social'] },
    { id: 'enhance-ability', name: 'Enhance Ability', school: 'Transmutation', classes: ['bard', 'cleric', 'druid', 'sorcerer'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Touch a creature to give it one enhancement: Bear\'s Endurance (advantage on Con checks, 2d6 temp HP), Bull\'s Strength (advantage on Str checks, double carry capacity), Cat\'s Grace, Eagle\'s Splendor, Fox\'s Cunning, or Owl\'s Wisdom. Upcast: +1 target per slot level above 2nd.', tags: ['buff', 'utility'] },
    { id: 'enlarge-reduce', name: 'Enlarge/Reduce', school: 'Transmutation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Enlarge: target doubles in size, advantage on Str checks and saves, +1d4 weapon damage. Reduce: target halves in size, disadvantage on Str, -1d4 weapon damage. Con save to resist.', tags: ['buff', 'debuff', 'transformation'] },
    { id: 'find-steed', name: 'Find Steed', school: 'Conjuration', classes: ['paladin'], castingTime: '10 minutes', range: '30 feet', components: 'V, S', duration: 'Instantaneous', description: 'Summon a spirit in form of warhorse, pony, camel, elk, or mastiff. Mount has Int 6, understands one language, and you share telepathic bond. Spells targeting only you can also target mount.', tags: ['summoning', 'utility'] },
    { id: 'find-traps', name: 'Find Traps', school: 'Divination', classes: ['cleric', 'druid', 'ranger'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Instantaneous', description: 'Sense the presence of any trap within line of sight and within range. You learn the general nature of the danger posed by each trap but not its location.', tags: ['detection', 'utility'] },
    { id: 'flame-blade', name: 'Flame Blade', school: 'Evocation', classes: ['druid'], castingTime: '1 bonus action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Create a fiery blade of flame in your free hand. Melee spell attack deals 3d6 fire damage on hit. As bonus action, re-evoke blade if dropped. Sheds bright light 10 ft, dim 10 ft. Upcast: +1d6 per 2 slot levels above 2nd.', tags: ['damage', 'fire', 'combat'] },
    { id: 'flaming-sphere', name: 'Flaming Sphere', school: 'Conjuration', classes: ['druid', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create a 5-foot diameter sphere of fire. Creatures ending turn within 5 feet make Dex save, taking 2d6 fire damage on fail (half on success). As bonus action, move sphere up to 30 feet. Ignites flammable objects. Upcast: +1d6 per slot level above 2nd.', tags: ['damage', 'fire', 'control'] },
    { id: 'gentle-repose', name: 'Gentle Repose', school: 'Necromancy', classes: ['cleric', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '10 days', description: 'Touch a corpse. It is protected from decay and can\'t become undead. Days spent under spell don\'t count against resurrection time limits.', tags: ['utility', 'ritual'] },
    { id: 'gust-of-wind', name: 'Gust of Wind', school: 'Evocation', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Self (60-foot line)', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create 60-foot long, 10-foot wide line of strong wind. Creatures starting turn in line must succeed Str save or be pushed 15 feet. Any creature in line must spend 2 feet of movement per foot moved toward you. Disperses gas/vapor, extinguishes open flames.', tags: ['control', 'terrain'] },
    { id: 'heat-metal', name: 'Heat Metal', school: 'Transmutation', classes: ['bard', 'druid'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Choose manufactured metal object. Creatures in contact take 2d8 fire damage. If holding object, must make Con save or drop it. If can\'t drop (armor), disadvantage on attacks and ability checks until start of your next turn. Can reactivate each turn as bonus action. Upcast: +1d8 per slot level above 2nd.', tags: ['damage', 'fire', 'debuff'] },
    { id: 'hold-person', name: 'Hold Person', school: 'Enchantment', classes: ['bard', 'cleric', 'druid', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Target humanoid must succeed Wis save or be paralyzed. Target repeats save at end of each turn. Upcast: +1 target per slot level above 2nd.', tags: ['control', 'debuff'] },
    { id: 'invisibility', name: 'Invisibility', school: 'Illusion', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Creature you touch becomes invisible until spell ends. Anything target wears or carries is also invisible. Spell ends if target attacks or casts a spell. Upcast: +1 target per slot level above 2nd.', tags: ['utility', 'stealth'] },
    { id: 'knock', name: 'Knock', school: 'Transmutation', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V', duration: 'Instantaneous', description: 'Choose an object that is locked. It becomes unlocked (mundane locks) or suppressed for 10 minutes (magical locks like arcane lock). Object is heard from up to 300 feet away.', tags: ['utility'] },
    { id: 'lesser-restoration', name: 'Lesser Restoration', school: 'Abjuration', classes: ['bard', 'cleric', 'druid', 'paladin', 'ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instantaneous', description: 'Touch a creature and end one disease or one condition afflicting it: blinded, deafened, paralyzed, or poisoned.', tags: ['healing', 'restoration'] },
    { id: 'levitate', name: 'Levitate', school: 'Transmutation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'One creature or object rises vertically up to 20 feet and remains suspended. Target can move only by pushing/pulling fixed objects. Unwilling creature makes Con save. Can change altitude up to 20 feet per turn.', tags: ['control', 'utility'] },
    { id: 'locate-animals-or-plants', name: 'Locate Animals or Plants', school: 'Divination', classes: ['bard', 'druid', 'ranger'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Instantaneous', description: 'Name a specific kind of beast or plant. Learn direction and distance to closest one within 5 miles.', tags: ['detection', 'nature', 'ritual'] },
    { id: 'locate-object', name: 'Locate Object', school: 'Divination', classes: ['bard', 'cleric', 'druid', 'paladin', 'ranger', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Sense direction to an object you\'re familiar with or describe in detail, if within 1,000 feet. Can locate nearest of a general type. Can\'t locate if running water separates you.', tags: ['detection', 'utility'] },
    { id: 'magic-mouth', name: 'Magic Mouth', school: 'Illusion', classes: ['bard', 'wizard'], castingTime: '1 minute', range: '30 feet', components: 'V, S, M', duration: 'Until dispelled', description: 'Implant a message of 25 words or less into an object. When triggered by conditions you set, a mouth appears and delivers the message in your voice.', tags: ['utility', 'communication', 'ritual'] },
    { id: 'magic-weapon', name: 'Magic Weapon', school: 'Transmutation', classes: ['paladin', 'wizard'], castingTime: '1 bonus action', range: 'Touch', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Touch a nonmagical weapon. It becomes magical with +1 bonus to attack rolls and damage rolls. Upcast: +2 at 4th level, +3 at 6th level.', tags: ['buff', 'combat'] },
    { id: 'mirror-image', name: 'Mirror Image', school: 'Illusion', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '1 minute', description: 'Create 3 illusory duplicates. When attacked, roll d20 to determine if attack targets duplicate instead (11+ with 3 duplicates, 8+ with 2, 6+ with 1). Duplicate has AC 10 + Dex modifier and disappears when hit.', tags: ['defense', 'illusion'] },
    { id: 'misty-step', name: 'Misty Step', school: 'Conjuration', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Instantaneous', description: 'Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space you can see.', tags: ['mobility', 'teleportation'] },
    { id: 'moonbeam', name: 'Moonbeam', school: 'Evocation', classes: ['druid'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create 5-foot radius, 40-foot high cylinder of pale light. Creature entering or starting turn in area makes Con save, taking 2d10 radiant damage on fail (half on success). Shapechangers have disadvantage and revert if they fail. Move beam 60 feet as action. Upcast: +1d10 per slot level above 2nd.', tags: ['damage', 'radiant', 'control'] },
    { id: 'pass-without-trace', name: 'Pass without Trace', school: 'Abjuration', classes: ['druid', 'ranger'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'You and creatures within 30 feet gain +10 to Stealth checks and can\'t be tracked by nonmagical means (unless you choose to leave a trail).', tags: ['stealth', 'utility'] },
    { id: 'prayer-of-healing', name: 'Prayer of Healing', school: 'Evocation', classes: ['cleric'], castingTime: '10 minutes', range: '30 feet', components: 'V', duration: 'Instantaneous', description: 'Up to 6 creatures regain 2d8 + spellcasting modifier HP. No effect on undead or constructs. Upcast: +1d8 per slot level above 2nd.', tags: ['healing'] },
    { id: 'protection-from-poison', name: 'Protection from Poison', school: 'Abjuration', classes: ['cleric', 'druid', 'paladin', 'ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '1 hour', description: 'Neutralize one poison affecting target. Target has advantage on saves against poison and resistance to poison damage.', tags: ['defense', 'protection'] },
    { id: 'ray-of-enfeeblement', name: 'Ray of Enfeeblement', school: 'Necromancy', classes: ['warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Black beam of enervating energy. Ranged spell attack; on hit, target deals only half damage with weapon attacks using Strength. Target makes Con save at end of each turn to end effect.', tags: ['debuff'] },
    { id: 'rope-trick', name: 'Rope Trick', school: 'Transmutation', classes: ['wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', description: 'Touch a rope up to 60 feet long. One end rises into the air and an invisible entrance to extradimensional space opens at the top. Space holds up to 8 Medium creatures. Rope can be pulled up. Attacks and spells can\'t cross into or out of space.', tags: ['utility', 'exploration'] },
    { id: 'scorching-ray', name: 'Scorching Ray', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Instantaneous', description: 'Create 3 rays of fire. Make ranged spell attack for each ray. Each ray deals 2d6 fire damage on hit. Can target one creature or several. Upcast: +1 ray per slot level above 2nd.', tags: ['damage', 'fire'] },
    { id: 'see-invisibility', name: 'See Invisibility', school: 'Divination', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '1 hour', description: 'See invisible creatures and objects as if visible. Also see into the Ethereal Plane.', tags: ['detection', 'utility'] },
    { id: 'shatter', name: 'Shatter', school: 'Evocation', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Painfully intense ringing in 10-foot radius sphere. Creatures make Con save, taking 3d8 thunder damage on fail (half on success). Creatures made of inorganic material have disadvantage. Nonmagical objects take damage automatically. Upcast: +1d8 per slot level above 2nd.', tags: ['damage', 'thunder', 'aoe'] },
    { id: 'silence', name: 'Silence', school: 'Illusion', classes: ['bard', 'cleric', 'ranger'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Create 20-foot-radius sphere of silence. No sound can be created within or pass through. Creatures inside are immune to thunder damage and deafened. Spells with verbal components can\'t be cast.', tags: ['control', 'terrain', 'ritual'] },
    { id: 'spider-climb', name: 'Spider Climb', school: 'Transmutation', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings, while leaving its hands free. It also gains a climbing speed equal to its walking speed.', tags: ['mobility', 'utility'] },
    { id: 'spike-growth', name: 'Spike Growth', school: 'Transmutation', classes: ['druid', 'ranger'], castingTime: '1 action', range: '150 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Ground in 20-foot radius sprouts hard spikes and thorns. Entering or moving through area costs 4 feet per foot moved and deals 2d4 piercing damage per 5 feet moved. Area is difficult terrain. Perception check to recognize hazard.', tags: ['control', 'terrain', 'damage'] },
    { id: 'spiritual-weapon', name: 'Spiritual Weapon', school: 'Evocation', classes: ['cleric'], castingTime: '1 bonus action', range: '60 feet', components: 'V, S', duration: '1 minute', description: 'Create a floating, spectral weapon. Make melee spell attack against creature within 5 feet of weapon, dealing 1d8 + spellcasting modifier force damage. As bonus action, move weapon 20 feet and repeat attack. Upcast: +1d8 per 2 slot levels above 2nd.', tags: ['damage', 'force', 'combat'] },
    { id: 'suggestion', name: 'Suggestion', school: 'Enchantment', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, M', duration: 'Concentration, 8 hours', description: 'Suggest a course of activity (limited to a sentence or two) to a creature you can see. Sounds reasonable to target. Wis save negates. Target pursues course of action to best of ability. Ends if trigger condition causes activity to be completed.', tags: ['charm', 'control', 'social'] },
    { id: 'warding-bond', name: 'Warding Bond', school: 'Abjuration', classes: ['cleric'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', description: 'Create a ward between you and one creature (requires pair of platinum rings). Target gains +1 AC, +1 saves, and resistance to all damage. When it takes damage, you take the same amount.', tags: ['defense', 'protection'] },
    { id: 'web', name: 'Web', school: 'Conjuration', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Fill 20-foot cube with thick, sticky webbing. Difficult terrain, lightly obscures. Creatures starting turn in webs or entering them must make Dex save or be restrained. Restrained creature can use action to make Str check to free itself. Webs are flammable; 5-foot cube burns away in 1 round, dealing 2d4 fire damage to any creature that starts turn in fire.', tags: ['control', 'terrain'] },
    { id: 'zone-of-truth', name: 'Zone of Truth', school: 'Enchantment', classes: ['bard', 'cleric', 'paladin'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: '10 minutes', description: 'Create 15-foot-radius sphere where creatures can\'t deliberately lie. Cha save to avoid effect (you know if they succeed). Affected creatures are aware of spell and can be evasive or refuse to answer.', tags: ['social', 'detection'] },
  ],

  // 3rd Level Spells
  3: [
    { id: 'animate-dead', name: 'Animate Dead', school: 'Necromancy', classes: ['cleric', 'wizard'], castingTime: '1 minute', range: '10 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Create an undead servant from a corpse. Target a pile of bones or corpse of a Medium or Small humanoid. It becomes a skeleton or zombie under your control for 24 hours. Upcast: +2 undead per slot level above 3rd.', tags: ['summoning', 'necromancy'] },
    { id: 'aura-of-vitality', name: 'Aura of Vitality', school: 'Evocation', classes: ['paladin'], castingTime: '1 action', range: 'Self (30-foot radius)', components: 'V', duration: 'Concentration, 1 minute', description: 'Healing energy radiates from you. As a bonus action, cause one creature in the aura to regain 2d6 HP.', tags: ['healing', 'aoe'] },
    { id: 'beacon-of-hope', name: 'Beacon of Hope', school: 'Abjuration', classes: ['cleric'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Choose any number of creatures within range. They have advantage on Wisdom saves and death saves, and regain max HP from any healing.', tags: ['buff', 'healing', 'support'] },
    { id: 'bestow-curse', name: 'Bestow Curse', school: 'Necromancy', classes: ['bard', 'cleric', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Touch a creature. Wis save or be cursed. Choose: disadvantage on checks/saves with one ability, disadvantage on attacks against you, Wis save each turn or lose action, your attacks deal extra 1d8 necrotic. Upcast: duration extends (8 hours at 4th, 24 hours at 5th, until dispelled at 7th+).', tags: ['debuff', 'curse'] },
    { id: 'blinding-smite', name: 'Blinding Smite', school: 'Evocation', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Next weapon hit deals extra 3d8 radiant damage and target must make Con save or be blinded until spell ends. Target can repeat save at end of each turn.', tags: ['damage', 'radiant', 'debuff'] },
    { id: 'call-lightning', name: 'Call Lightning', school: 'Conjuration', classes: ['druid'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Create a storm cloud 100 feet above you. Call down a bolt of lightning, dealing 3d10 lightning damage (Dex half) in 5-foot radius. Can call lightning each turn as action. +1d10 if already stormy. Upcast: +1d10 per slot level above 3rd.', tags: ['damage', 'lightning', 'aoe'] },
    { id: 'clairvoyance', name: 'Clairvoyance', school: 'Divination', classes: ['bard', 'cleric', 'sorcerer', 'wizard'], castingTime: '10 minutes', range: '1 mile', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Create an invisible sensor at a location you have seen or an obvious one you haven\'t. You can see or hear (not both) through the sensor. Switch senses as action.', tags: ['detection', 'utility'] },
    { id: 'conjure-animals', name: 'Conjure Animals', school: 'Conjuration', classes: ['druid', 'ranger'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Summon fey spirits as beasts. Choose: one CR 2 beast, two CR 1 beasts, four CR 1/2 beasts, or eight CR 1/4 beasts. They obey your commands. Upcast: doubles at 5th, 7th, 9th.', tags: ['summoning', 'nature'] },
    { id: 'counterspell', name: 'Counterspell', school: 'Abjuration', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 reaction', range: '60 feet', components: 'S', duration: 'Instantaneous', description: 'Attempt to interrupt a creature casting a spell. If spell is 3rd level or lower, it fails. Higher levels require ability check (DC 10 + spell level). Upcast: automatically counters spells of that level or lower.', tags: ['defense', 'reaction'] },
    { id: 'create-food-and-water', name: 'Create Food and Water', school: 'Conjuration', classes: ['cleric', 'paladin'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: 'Instantaneous', description: 'Create 45 pounds of food and 30 gallons of water, enough for 15 humanoids or 5 steeds for 24 hours.', tags: ['utility'] },
    { id: 'crusaders-mantle', name: "Crusader's Mantle", school: 'Evocation', classes: ['paladin'], castingTime: '1 action', range: 'Self (30-foot radius)', components: 'V', duration: 'Concentration, 1 minute', description: 'Holy power radiates from you. Nonhostile creatures within 30 feet (including you) deal extra 1d4 radiant damage with weapon attacks.', tags: ['buff', 'radiant', 'aoe'] },
    { id: 'daylight', name: 'Daylight', school: 'Evocation', classes: ['cleric', 'druid', 'paladin', 'ranger', 'sorcerer'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: '1 hour', description: 'Create 60-foot sphere of bright light and 60-foot dim light beyond that. If cast on object, can be covered. Dispels darkness spells of 3rd level or lower that overlap it.', tags: ['utility', 'light'] },
    { id: 'dispel-magic', name: 'Dispel Magic', school: 'Abjuration', classes: ['bard', 'cleric', 'druid', 'paladin', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Instantaneous', description: 'Choose creature, object, or magical effect within range. Any spell of 3rd level or lower ends. For higher level spells, make ability check (DC 10 + spell level). Upcast: automatically ends spells of that level or lower.', tags: ['utility'] },
    { id: 'elemental-weapon', name: 'Elemental Weapon', school: 'Transmutation', classes: ['paladin'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Touch a nonmagical weapon. It becomes magical with +1 to attack and deals +1d4 damage of acid, cold, fire, lightning, or thunder (your choice). Upcast: +2/+2d4 at 5th, +3/+3d4 at 7th.', tags: ['buff', 'combat'] },
    { id: 'fear', name: 'Fear', school: 'Illusion', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Self (30-foot cone)', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Project a phantasmal image of your worst fears. Each creature in 30-foot cone must make Wis save or drop what it\'s holding and become frightened. Frightened creatures must Dash away from you. Repeat save at end of turn if it can\'t see you.', tags: ['control', 'debuff', 'fear'] },
    { id: 'feign-death', name: 'Feign Death', school: 'Necromancy', classes: ['bard', 'cleric', 'druid', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', description: 'Touch a willing creature and put it in a cataleptic state indistinguishable from death. Target is blinded and incapacitated, speed drops to 0, resistance to all damage except psychic. Disease and poison suspended.', tags: ['utility', 'ritual'] },
    { id: 'fireball', name: 'Fireball', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '150 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'A bright streak flashes from your finger to a point you choose, then blossoms into an explosion of flame. Each creature in 20-foot sphere makes Dex save, taking 8d6 fire damage on fail (half on success). Ignites flammable objects. Upcast: +1d6 per slot level above 3rd.', tags: ['damage', 'fire', 'aoe'] },
    { id: 'fly', name: 'Fly', school: 'Transmutation', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Touch a willing creature. Target gains flying speed of 60 feet. When spell ends, target falls if still aloft. Upcast: +1 target per slot level above 3rd.', tags: ['mobility', 'buff'] },
    { id: 'gaseous-form', name: 'Gaseous Form', school: 'Transmutation', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Transform a willing creature into a misty cloud. Flying speed 10 feet, can pass through small holes, advantage on Str/Dex/Con saves, resistance to nonmagical damage. Can\'t attack or cast spells.', tags: ['utility', 'transformation'] },
    { id: 'glyph-of-warding', name: 'Glyph of Warding', school: 'Abjuration', classes: ['bard', 'cleric', 'wizard'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Until dispelled or triggered', description: 'Inscribe a glyph that harms creatures that trigger it. Choose explosive runes (5d8 acid, cold, fire, lightning, or thunder; Dex half) or spell glyph (stores a spell up to 3rd level that targets triggering creature). Upcast: explosive adds 1d8 per slot level, spell can be of slot level used.', tags: ['damage', 'trap'] },
    { id: 'haste', name: 'Haste', school: 'Transmutation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Target\'s speed is doubled, +2 AC, advantage on Dex saves, and additional action each turn (Attack with one weapon, Dash, Disengage, Hide, or Use Object only). When spell ends, target can\'t move or take actions until after its next turn.', tags: ['buff', 'combat'] },
    { id: 'hypnotic-pattern', name: 'Hypnotic Pattern', school: 'Illusion', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'S, M', duration: 'Concentration, 1 minute', description: 'Create a twisting pattern of colors in a 30-foot cube. Creatures that see it must make Wis save or be charmed (incapacitated, speed 0). Effect ends for creature if it takes damage or another creature uses action to shake it.', tags: ['control', 'debuff'] },
    { id: 'leomund-tiny-hut', name: "Leomund's Tiny Hut", school: 'Evocation', classes: ['bard', 'wizard'], castingTime: '1 minute', range: 'Self (10-foot-radius hemisphere)', components: 'V, S, M', duration: '8 hours', description: 'Create a dome of force around and above you. Nine creatures of Medium size or smaller can fit. Creatures and objects inside when cast can move freely. Spells can\'t be cast through it. Climate is comfortable inside.', tags: ['utility', 'protection', 'ritual'] },
    { id: 'lightning-bolt', name: 'Lightning Bolt', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self (100-foot line)', components: 'V, S, M', duration: 'Instantaneous', description: 'A stroke of lightning forming a 100-foot long, 5-foot wide line blasts out from you. Each creature in the line makes Dex save, taking 8d6 lightning damage on fail (half on success). Ignites flammable objects. Upcast: +1d6 per slot level above 3rd.', tags: ['damage', 'lightning', 'aoe'] },
    { id: 'magic-circle', name: 'Magic Circle', school: 'Abjuration', classes: ['cleric', 'paladin', 'warlock', 'wizard'], castingTime: '1 minute', range: '10 feet', components: 'V, S, M', duration: '1 hour', description: 'Create 10-foot-radius, 20-foot-tall cylinder of magical energy. Choose celestials, elementals, fey, fiends, or undead. Chosen type can\'t willingly enter, has disadvantage on attacks against creatures inside, and can\'t charm, frighten, or possess creatures inside. Upcast: duration increases.', tags: ['protection', 'defense'] },
    { id: 'major-image', name: 'Major Image', school: 'Illusion', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Create an image no larger than a 20-foot cube with sound, smell, and temperature. Can move within range. Investigation check to determine illusion. Upcast at 6th+: lasts until dispelled without concentration.', tags: ['illusion', 'utility'] },
    { id: 'mass-healing-word', name: 'Mass Healing Word', school: 'Evocation', classes: ['cleric'], castingTime: '1 bonus action', range: '60 feet', components: 'V', duration: 'Instantaneous', description: 'Up to 6 creatures you can see regain 1d4 + spellcasting modifier HP. No effect on undead or constructs. Upcast: +1d4 per slot level above 3rd.', tags: ['healing', 'aoe'] },
    { id: 'meld-into-stone', name: 'Meld into Stone', school: 'Transmutation', classes: ['cleric', 'druid'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '8 hours', description: 'Step into a stone object or surface large enough to contain your body. You can\'t see what happens outside, but can hear. You can cast spells on yourself while inside. If stone is damaged, you\'re expelled and take 6d6 bludgeoning.', tags: ['utility', 'protection', 'ritual'] },
    { id: 'nondetection', name: 'Nondetection', school: 'Abjuration', classes: ['bard', 'ranger', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '8 hours', description: 'Hide a creature or object from divination magic. Target can\'t be targeted by divination magic or perceived through magical scrying sensors.', tags: ['protection', 'utility'] },
    { id: 'phantom-steed', name: 'Phantom Steed', school: 'Illusion', classes: ['wizard'], castingTime: '1 minute', range: '30 feet', components: 'V, S', duration: '1 hour', description: 'Create a Large quasi-real horse. It has stats of a riding horse, can only be ridden by a creature you designate, and has speed 100 feet. Fades over 1 minute if spell ends.', tags: ['utility', 'mobility', 'ritual'] },
    { id: 'plant-growth', name: 'Plant Growth', school: 'Transmutation', classes: ['bard', 'druid', 'ranger'], castingTime: '1 action or 8 hours', range: '150 feet', components: 'V, S', duration: 'Instantaneous', description: 'Action: Plants in 100-foot radius become thick and overgrown (4 feet of movement to move 1 foot). 8 hours: Enriches plants in half-mile radius, yielding twice the normal harvest for 1 year.', tags: ['control', 'terrain', 'utility'] },
    { id: 'protection-from-energy', name: 'Protection from Energy', school: 'Abjuration', classes: ['cleric', 'druid', 'ranger', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Touch a willing creature. It has resistance to acid, cold, fire, lightning, or thunder damage (your choice) for the duration.', tags: ['defense', 'protection'] },
    { id: 'remove-curse', name: 'Remove Curse', school: 'Abjuration', classes: ['cleric', 'paladin', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Instantaneous', description: 'At your touch, all curses affecting one creature or object end. If object is a cursed magic item, the curse remains but the spell breaks the owner\'s attunement so it can be removed.', tags: ['restoration', 'utility'] },
    { id: 'revivify', name: 'Revivify', school: 'Necromancy', classes: ['cleric', 'paladin'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Touch a creature that died within the last minute. It returns to life with 1 HP. Can\'t restore missing body parts. Can\'t return creatures that died of old age.', tags: ['healing', 'resurrection'] },
    { id: 'sending', name: 'Sending', school: 'Evocation', classes: ['bard', 'cleric', 'wizard'], castingTime: '1 action', range: 'Unlimited', components: 'V, S, M', duration: 'Instantaneous', description: 'Send a 25-word message to a creature you\'re familiar with. It hears the message, recognizes you, and can reply immediately with 25 words. Can reach any plane of existence.', tags: ['communication', 'utility'] },
    { id: 'sleet-storm', name: 'Sleet Storm', school: 'Conjuration', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '150 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create 40-foot-radius, 20-foot-high cylinder of freezing rain and sleet. Ground is difficult terrain. Creature entering or starting turn in area must make Dex save or fall prone. Concentration checks for spellcasters in area.', tags: ['control', 'terrain'] },
    { id: 'slow', name: 'Slow', school: 'Transmutation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Up to 6 creatures in 40-foot cube make Wis save. On fail: half speed, -2 AC and Dex saves, can\'t use reactions, can use either action or bonus action (not both), can\'t make more than one attack. Spells cast on 1-2 on d6 take effect next turn instead. Repeat save at end of each turn.', tags: ['debuff', 'control'] },
    { id: 'speak-with-dead', name: 'Speak with Dead', school: 'Necromancy', classes: ['bard', 'cleric'], castingTime: '1 action', range: '10 feet', components: 'V, S, M', duration: '10 minutes', description: 'Ask a corpse up to 5 questions. Corpse knows only what it knew in life, isn\'t compelled to be truthful, and answers can be cryptic. Can\'t be used on same corpse within 10 days.', tags: ['utility', 'communication'] },
    { id: 'speak-with-plants', name: 'Speak with Plants', school: 'Transmutation', classes: ['bard', 'druid', 'ranger'], castingTime: '1 action', range: 'Self (30-foot radius)', components: 'V, S', duration: '10 minutes', description: 'Imbue plants with limited sentience. They can answer questions, describe events in last day, follow simple requests like moving branches. Turn difficult terrain into normal or vice versa.', tags: ['utility', 'communication', 'nature'] },
    { id: 'spirit-guardians', name: 'Spirit Guardians', school: 'Conjuration', classes: ['cleric'], castingTime: '1 action', range: 'Self (15-foot radius)', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Spirits surround you in 15-foot radius. Creatures you designate are unaffected. Others entering or starting turn in area must make Wis save, taking 3d8 radiant (good/neutral caster) or necrotic (evil caster) damage on fail (half on success). Area is difficult terrain for enemies. Upcast: +1d8 per slot level above 3rd.', tags: ['damage', 'radiant', 'aoe', 'control'] },
    { id: 'stinking-cloud', name: 'Stinking Cloud', school: 'Conjuration', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '90 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create 20-foot-radius sphere of yellow, nauseating gas. Heavily obscures. Creatures starting turn in cloud must make Con save or spend action retching and reeling (can still move). Creatures immune to poison are unaffected.', tags: ['control', 'debuff'] },
    { id: 'tongues', name: 'Tongues', school: 'Divination', classes: ['bard', 'cleric', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, M', duration: '1 hour', description: 'Target gains ability to understand any spoken language and speak so that any creature that knows at least one language can understand them.', tags: ['utility', 'communication'] },
    { id: 'vampiric-touch', name: 'Vampiric Touch', school: 'Necromancy', classes: ['warlock', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Your touch deals 3d6 necrotic damage (melee spell attack) and you regain HP equal to half the damage dealt. On each turn while spell lasts, you can attack again as action. Upcast: +1d6 per slot level above 3rd.', tags: ['damage', 'necrotic', 'healing'] },
    { id: 'water-breathing', name: 'Water Breathing', school: 'Transmutation', classes: ['druid', 'ranger', 'sorcerer', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: '24 hours', description: 'Grant up to 10 willing creatures the ability to breathe underwater until the spell ends. Creatures retain normal breathing mode.', tags: ['utility', 'ritual'] },
    { id: 'water-walk', name: 'Water Walk', school: 'Transmutation', classes: ['cleric', 'druid', 'ranger', 'sorcerer'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: '1 hour', description: 'Grant up to 10 willing creatures ability to walk on any liquid as if solid ground. If target is submerged, spell carries it to surface at 60 feet per round.', tags: ['utility', 'ritual'] },
    { id: 'wind-wall', name: 'Wind Wall', school: 'Evocation', classes: ['druid', 'ranger'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create wall of wind up to 50 feet long, 15 feet high, 1 foot thick. Creatures in wall make Str save or take 3d8 bludgeoning. Wall keeps fog, smoke, and small flying creatures out. Ranged weapon attacks that cross it automatically miss.', tags: ['control', 'damage'] },
  ],

  // 4th Level Spells
  4: [
    { id: 'aura-of-life', name: 'Aura of Life', school: 'Abjuration', classes: ['paladin'], castingTime: '1 action', range: 'Self (30-foot radius)', components: 'V', duration: 'Concentration, 10 minutes', description: 'Life-preserving energy radiates from you. Nonhostile creatures in aura have resistance to necrotic damage. Nonhostile creature starting turn in aura with 0 HP regains 1 HP.', tags: ['protection', 'healing', 'aoe'] },
    { id: 'aura-of-purity', name: 'Aura of Purity', school: 'Abjuration', classes: ['paladin'], castingTime: '1 action', range: 'Self (30-foot radius)', components: 'V', duration: 'Concentration, 10 minutes', description: 'Purifying energy radiates from you. Nonhostile creatures in aura can\'t become diseased, have resistance to poison damage, and advantage on saves against blinded, charmed, deafened, frightened, paralyzed, poisoned, stunned.', tags: ['protection', 'buff', 'aoe'] },
    { id: 'banishment', name: 'Banishment', school: 'Abjuration', classes: ['cleric', 'paladin', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Banish a creature you can see. Cha save or be sent to a harmless demiplane (native to this plane) or home plane (extraplanar, can\'t return for duration). If concentration maintained for full duration, extraplanar creatures don\'t return. Upcast: +1 target per slot level above 4th.', tags: ['control', 'banishment'] },
    { id: 'blight', name: 'Blight', school: 'Necromancy', classes: ['druid', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: 'Instantaneous', description: 'Necromantic energy washes over a creature. Con save; 8d8 necrotic damage on fail (half on success). Plants and magical plant creatures have disadvantage and take max damage. Upcast: +1d8 per slot level above 4th.', tags: ['damage', 'necrotic'] },
    { id: 'compulsion', name: 'Compulsion', school: 'Enchantment', classes: ['bard'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Creatures of your choice within range that can hear you must make Wis save or be affected. Before each of your turns, you can designate a direction. Affected creatures must use as much movement as possible to move in that direction. They can repeat save after moving.', tags: ['control', 'charm'] },
    { id: 'confusion', name: 'Confusion', school: 'Enchantment', classes: ['bard', 'druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '90 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Creatures in 10-foot sphere must make Wis save or be unable to take reactions and roll d10 each turn to determine behavior (1: move randomly, 2-6: no action/movement, 7-8: melee attack random adjacent creature, 9-10: act normally). Repeat save at end of turn. Upcast: +5-foot radius per slot level above 4th.', tags: ['control', 'debuff'] },
    { id: 'conjure-minor-elementals', name: 'Conjure Minor Elementals', school: 'Conjuration', classes: ['druid', 'wizard'], castingTime: '1 minute', range: '90 feet', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Summon elementals. Choose: one CR 2 elemental, two CR 1, four CR 1/2, or eight CR 1/4. They obey your verbal commands. Upcast: doubles at 6th, 8th.', tags: ['summoning'] },
    { id: 'conjure-woodland-beings', name: 'Conjure Woodland Beings', school: 'Conjuration', classes: ['druid', 'ranger'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Summon fey creatures. Choose: one CR 2 fey, two CR 1, four CR 1/2, or eight CR 1/4. They obey your verbal commands. Upcast: doubles at 6th, 8th.', tags: ['summoning', 'nature'] },
    { id: 'control-water', name: 'Control Water', school: 'Transmutation', classes: ['cleric', 'druid', 'wizard'], castingTime: '1 action', range: '300 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Control freestanding water in 100-foot cube. Choose: Flood (raise level up to 20 feet), Part Water (trench through water up to 20 feet deep), Redirect Flow (cause flowing water to move in direction you choose), or Whirlpool (25-foot vortex that deals 2d8 bludgeoning).', tags: ['control', 'terrain'] },
    { id: 'death-ward', name: 'Death Ward', school: 'Abjuration', classes: ['cleric', 'paladin'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '8 hours', description: 'Touch a creature and grant it ward against death. First time target would drop to 0 HP, target drops to 1 HP instead and spell ends. Also negates first instant death effect that would kill target.', tags: ['protection', 'defense'] },
    { id: 'dimension-door', name: 'Dimension Door', school: 'Conjuration', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '500 feet', components: 'V', duration: 'Instantaneous', description: 'Teleport to a spot within range you can see, visualize, or describe. Can bring one willing creature of your size or smaller. If destination is occupied, both take 4d6 force damage.', tags: ['mobility', 'teleportation'] },
    { id: 'divination', name: 'Divination', school: 'Divination', classes: ['cleric'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Instantaneous', description: 'Contact your deity or divine proxy. Ask a single question about a specific goal, event, or activity to occur within 7 days. GM offers truthful reply: short phrase, cryptic rhyme, or omen.', tags: ['utility', 'knowledge', 'ritual'] },
    { id: 'dominate-beast', name: 'Dominate Beast', school: 'Enchantment', classes: ['druid', 'sorcerer'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Charm a beast you can see. Wis save (advantage if fighting you). You have telepathic link and can command it (no action required). Can use reaction to force exact control of action. New save when it takes damage. Upcast: duration increases (1 hour at 5th, 8 hours at 6th, 24 hours at 7th+).', tags: ['charm', 'control'] },
    { id: 'evards-black-tentacles', name: "Evard's Black Tentacles", school: 'Conjuration', classes: ['wizard'], castingTime: '1 action', range: '90 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Squirming, ebony tentacles fill 20-foot square. Difficult terrain. Creature entering or starting turn there must make Dex save or take 3d6 bludgeoning and be restrained. Restrained creature can use action to make Str/Dex check to escape.', tags: ['control', 'damage'] },
    { id: 'fabricate', name: 'Fabricate', school: 'Transmutation', classes: ['wizard'], castingTime: '10 minutes', range: '120 feet', components: 'V, S', duration: 'Instantaneous', description: 'Convert raw materials into finished products. Large or smaller object in 10-foot cube, or up to eight connected 5-foot cubes for larger objects. Requires proficiency with artisan\'s tools for complex objects.', tags: ['utility'] },
    { id: 'fire-shield', name: 'Fire Shield', school: 'Evocation', classes: ['wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: '10 minutes', description: 'Choose warm or chill shield. Warm: resistance to cold damage, creature hitting you with melee attack takes 2d8 fire. Chill: resistance to fire damage, creature hitting you takes 2d8 cold. Sheds bright light 10 feet, dim 10 feet.', tags: ['defense', 'damage', 'retaliation'] },
    { id: 'freedom-of-movement', name: 'Freedom of Movement', school: 'Abjuration', classes: ['bard', 'cleric', 'druid', 'ranger'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', description: 'Touch a willing creature. Its movement is unaffected by difficult terrain. Spells and magical effects can\'t reduce speed or cause paralysis/restraint. Can spend 5 feet of movement to escape nonmagical restraints. No penalty for moving underwater.', tags: ['buff', 'mobility'] },
    { id: 'giant-insect', name: 'Giant Insect', school: 'Transmutation', classes: ['druid'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Transform up to 10 centipedes, 3 spiders, 5 wasps, or 1 scorpion into giant versions. They obey your verbal commands. In combat, they act on your turn.', tags: ['summoning', 'transformation'] },
    { id: 'greater-invisibility', name: 'Greater Invisibility', school: 'Illusion', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: 'Concentration, 1 minute', description: 'You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible. The target can attack and cast spells without ending the invisibility.', tags: ['stealth', 'utility'] },
    { id: 'guardian-of-faith', name: 'Guardian of Faith', school: 'Conjuration', classes: ['cleric'], castingTime: '1 action', range: '30 feet', components: 'V', duration: '8 hours', description: 'Create a Large spectral guardian. Hostile creature moving within 10 feet of guardian for first time must make Dex save, taking 20 radiant damage on fail (half on success). Guardian vanishes when it has dealt 60 total damage.', tags: ['damage', 'radiant', 'protection'] },
    { id: 'hallucinatory-terrain', name: 'Hallucinatory Terrain', school: 'Illusion', classes: ['bard', 'druid', 'warlock', 'wizard'], castingTime: '10 minutes', range: '300 feet', components: 'V, S, M', duration: '24 hours', description: 'Make natural terrain in 150-foot cube look, sound, and smell like some other natural terrain. Structures, equipment, and creatures not concealed. Investigation check to see through illusion.', tags: ['illusion', 'terrain'] },
    { id: 'ice-storm', name: 'Ice Storm', school: 'Evocation', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '300 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Hail stones pound down in 20-foot radius, 40-foot high cylinder. Creatures make Dex save, taking 2d8 bludgeoning + 4d6 cold on fail (half on success). Area becomes difficult terrain until end of your next turn. Upcast: bludgeoning increases 1d8 per slot level above 4th.', tags: ['damage', 'cold', 'control', 'aoe'] },
    { id: 'locate-creature', name: 'Locate Creature', school: 'Divination', classes: ['bard', 'cleric', 'druid', 'paladin', 'ranger', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Sense direction to a specific creature you\'re familiar with or nearest of a specific type, if within 1,000 feet. Can\'t locate if running water separates you or if target is polymorphed.', tags: ['detection', 'utility'] },
    { id: 'mordenkainens-faithful-hound', name: "Mordenkainen's Faithful Hound", school: 'Conjuration', classes: ['wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: '8 hours', description: 'Conjure a phantom watchdog. It is invisible to all but you, can\'t be harmed, and barks when any creature comes within 30 feet. At the start of your turns, the hound can bite one creature within 5 feet (melee attack, 4d8 piercing).', tags: ['protection', 'summoning'] },
    { id: 'mordenkainens-private-sanctum', name: "Mordenkainen's Private Sanctum", school: 'Abjuration', classes: ['wizard'], castingTime: '10 minutes', range: '120 feet', components: 'V, S, M', duration: '24 hours', description: 'Make area within 100-foot cube magically secure. Choose: sound can\'t pass through, area is dark and filled with fog, divination spells can\'t target creatures/areas inside, nothing can teleport in, planar travel blocked. Upcast: +100-foot cube per slot level above 4th.', tags: ['protection', 'utility'] },
    { id: 'otilukes-resilient-sphere', name: "Otiluke's Resilient Sphere", school: 'Evocation', classes: ['wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create shimmering sphere around Large or smaller creature/object. Dex save negates (willing creatures can fail intentionally). Creature inside can breathe. Nothing can pass through physically or magically. Sphere weighs nothing and can be pushed.', tags: ['protection', 'control'] },
    { id: 'phantasmal-killer', name: 'Phantasmal Killer', school: 'Illusion', classes: ['wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Create an illusory manifestation of a creature\'s deepest fears. Target must make Wis save or become frightened. At end of each turn, target makes another Wis save. On fail: 4d10 psychic damage. On success: spell ends. Upcast: +1d10 per slot level above 4th.', tags: ['damage', 'psychic', 'fear', 'illusion'] },
    { id: 'polymorph', name: 'Polymorph', school: 'Transmutation', classes: ['bard', 'druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Transform a creature into a new beast form. Wis save (unwilling). New form\'s CR must be equal to or less than target\'s level (or CR). Game statistics replaced by new form\'s. Limited actions by new form\'s capabilities. Reverts when reduced to 0 HP.', tags: ['transformation', 'utility'] },
    { id: 'staggering-smite', name: 'Staggering Smite', school: 'Evocation', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Next weapon hit deals extra 4d6 psychic damage and target must make Wis save or have disadvantage on attacks and ability checks, and can\'t take reactions, until end of its next turn.', tags: ['damage', 'psychic', 'debuff'] },
    { id: 'stoneskin', name: 'Stoneskin', school: 'Abjuration', classes: ['druid', 'ranger', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Touch a willing creature. Until the spell ends, the target has resistance to nonmagical bludgeoning, piercing, and slashing damage.', tags: ['defense', 'buff'] },
    { id: 'wall-of-fire', name: 'Wall of Fire', school: 'Evocation', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create wall of fire up to 60 feet long, 20 feet high, 1 foot thick (or ringed, 20-foot diameter, 20 feet high). One side (your choice) deals 5d8 fire damage to creatures within 10 feet (Dex half). Creature entering wall or ending turn there takes 5d8 (Dex half). Upcast: +1d8 per slot level above 4th.', tags: ['damage', 'fire', 'control'] },
  ],

  // 5th Level Spells
  5: [
    { id: 'animate-objects', name: 'Animate Objects', school: 'Transmutation', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Animate up to 10 nonmagical objects. Objects follow your verbal commands and act on your turn. Statistics based on size (Tiny: AC 18, HP 20, +8 attack, 1d4+4 damage). Upcast: +2 objects per slot level above 5th.', tags: ['summoning', 'utility'] },
    { id: 'antilife-shell', name: 'Antilife Shell', school: 'Abjuration', classes: ['druid'], castingTime: '1 action', range: 'Self (10-foot radius)', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Create shimmering barrier around you. Creatures other than undead and constructs can\'t pass through or reach through to touch you or attack you with melee attacks.', tags: ['protection', 'defense'] },
    { id: 'awaken', name: 'Awaken', school: 'Transmutation', classes: ['bard', 'druid'], castingTime: '8 hours', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Touch a Huge or smaller beast or plant. Target gains Int 10 and ability to speak one language you know. If beast, it is charmed by you for 30 days (or until you or allies harm it).', tags: ['utility', 'nature'] },
    { id: 'banishing-smite', name: 'Banishing Smite', school: 'Abjuration', classes: ['paladin'], castingTime: '1 bonus action', range: 'Self', components: 'V', duration: 'Concentration, 1 minute', description: 'Next weapon hit deals extra 5d10 force damage. If this brings target to 50 HP or fewer, it must make Cha save or be banished. If native to different plane, it returns there. Otherwise, sent to harmless demiplane until spell ends.', tags: ['damage', 'force', 'banishment'] },
    { id: 'bigbys-hand', name: "Bigby's Hand", school: 'Evocation', classes: ['wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create Large hand of shimmering force. AC 20, HP equal to your HP max, Str 26. Can use bonus action for: Clenched Fist (melee attack, 4d8 force), Forceful Hand (push), Grasping Hand (grapple), or Interposing Hand (half cover). Upcast: +2d8 fist, +2d6 grasping per slot level above 5th.', tags: ['damage', 'control', 'force'] },
    { id: 'circle-of-power', name: 'Circle of Power', school: 'Abjuration', classes: ['paladin'], castingTime: '1 action', range: 'Self (30-foot radius)', components: 'V', duration: 'Concentration, 10 minutes', description: 'Divine energy radiates from you. Friendly creatures in aura have advantage on saving throws against magical effects. If a save would normally halve damage, they take no damage on success.', tags: ['protection', 'buff', 'aoe'] },
    { id: 'cloudkill', name: 'Cloudkill', school: 'Conjuration', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Create 20-foot-radius sphere of poisonous, yellowish-green fog. Heavily obscures. Creature entering or starting turn in fog must make Con save, taking 5d8 poison damage on fail (half on success). Fog moves 10 feet away from you at start of your turn. Upcast: +1d8 per slot level above 5th.', tags: ['damage', 'poison', 'control'] },
    { id: 'commune', name: 'Commune', school: 'Divination', classes: ['cleric'], castingTime: '1 minute', range: 'Self', components: 'V, S, M', duration: '1 minute', description: 'Contact your deity or proxy. Ask up to 3 yes-or-no questions. Divine beings aren\'t omniscient. If question doesn\'t apply, answer is "unclear."', tags: ['utility', 'knowledge', 'ritual'] },
    { id: 'commune-with-nature', name: 'Commune with Nature', school: 'Divination', classes: ['druid', 'ranger'], castingTime: '1 minute', range: 'Self', components: 'V, S', duration: 'Instantaneous', description: 'Become one with nature. Learn up to 3 facts about terrain within 3 miles (or 300 feet underground): terrain, bodies of water, prevalent plants/minerals/animals/peoples, powerful celestials/fey/fiends/elementals/undead.', tags: ['utility', 'detection', 'ritual'] },
    { id: 'cone-of-cold', name: 'Cone of Cold', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self (60-foot cone)', components: 'V, S, M', duration: 'Instantaneous', description: 'Blast of cold air erupts from your hands. Each creature in 60-foot cone makes Con save, taking 8d8 cold damage on fail (half on success). Creature killed by this spell becomes frozen statue. Upcast: +1d8 per slot level above 5th.', tags: ['damage', 'cold', 'aoe'] },
    { id: 'conjure-elemental', name: 'Conjure Elemental', school: 'Conjuration', classes: ['druid', 'wizard'], castingTime: '1 minute', range: '90 feet', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Summon elemental of CR 5 or lower. It obeys your verbal commands. If concentration breaks, elemental becomes hostile. Upcast: +1 CR per slot level above 5th.', tags: ['summoning'] },
    { id: 'contagion', name: 'Contagion', school: 'Necromancy', classes: ['cleric', 'druid'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '7 days', description: 'Touch a creature and afflict it with a disease. Target must make 3 Con saves (end of each turn). 3 failures: disease takes effect (Blinding Sickness, Filth Fever, Flesh Rot, Mindfire, Seizure, or Slimy Doom). 3 successes: disease ends.', tags: ['debuff', 'disease'] },
    { id: 'contact-other-plane', name: 'Contact Other Plane', school: 'Divination', classes: ['warlock', 'wizard'], castingTime: '1 minute', range: 'Self', components: 'V', duration: '1 minute', description: 'Contact a demigod, spirit, or alien entity. DC 15 Int save or take 6d6 psychic damage and be insane until long rest. On success, ask up to 5 questions and receive one-word answers.', tags: ['utility', 'knowledge', 'ritual'] },
    { id: 'creation', name: 'Creation', school: 'Illusion', classes: ['sorcerer', 'wizard'], castingTime: '1 minute', range: '30 feet', components: 'V, S, M', duration: 'Special', description: 'Pull wisps of shadow to create nonliving object of vegetable matter (24 hours), stone/crystal (12 hours), precious metals (1 hour), gems (10 minutes), adamantine/mithral (1 minute). Size up to 5-foot cube. Upcast: +5-foot cube per slot level above 5th.', tags: ['utility'] },
    { id: 'destructive-wave', name: 'Destructive Wave', school: 'Evocation', classes: ['paladin'], castingTime: '1 action', range: 'Self (30-foot radius)', components: 'V', duration: 'Instantaneous', description: 'Strike ground and divine energy ripples out. Creatures you choose within 30 feet must make Con save, taking 5d6 thunder + 5d6 radiant/necrotic damage on fail (half on success), and be knocked prone on fail.', tags: ['damage', 'thunder', 'radiant', 'aoe'] },
    { id: 'dispel-evil-and-good', name: 'Dispel Evil and Good', school: 'Abjuration', classes: ['cleric', 'paladin'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Shimmering energy surrounds you. Aberrations, celestials, elementals, fey, fiends, undead have disadvantage on attacks against you. Can use action to: Break Enchantment (end charm/frighten/possession on one creature) or Dismissal (melee spell attack to send creature to home plane, Cha save negates).', tags: ['protection', 'banishment'] },
    { id: 'dominate-person', name: 'Dominate Person', school: 'Enchantment', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Charm a humanoid. Wis save (advantage if fighting you). Telepathic link, can command as action. Can use reaction for precise control. New save when takes damage. Upcast: duration increases (10 min at 6th, 1 hour at 7th, 8 hours at 8th, 24 hours at 9th).', tags: ['charm', 'control'] },
    { id: 'dream', name: 'Dream', school: 'Illusion', classes: ['bard', 'warlock', 'wizard'], castingTime: '1 minute', range: 'Special', components: 'V, S, M', duration: '8 hours', description: 'Shape a creature\'s dreams. Target must be known to you and on same plane. Messenger enters target\'s dreams and can converse for duration. Can make messenger terrifying (Wis save or 3d6 psychic damage and no benefit from rest).', tags: ['communication', 'illusion', 'psychic'] },
    { id: 'flame-strike', name: 'Flame Strike', school: 'Evocation', classes: ['cleric'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Vertical column of divine fire roars down in 10-foot-radius, 40-foot-high cylinder. Creatures make Dex save, taking 4d6 fire + 4d6 radiant on fail (half on success). Upcast: +1d6 fire or radiant (your choice) per slot level above 5th.', tags: ['damage', 'fire', 'radiant', 'aoe'] },
    { id: 'geas', name: 'Geas', school: 'Enchantment', classes: ['bard', 'cleric', 'druid', 'paladin', 'wizard'], castingTime: '1 minute', range: '60 feet', components: 'V', duration: '30 days', description: 'Place magical command on a creature. Wis save negates. If creature acts against command, takes 5d10 psychic damage (once per day). Upcast: 1 year at 7th, permanent at 9th.', tags: ['charm', 'control'] },
    { id: 'greater-restoration', name: 'Greater Restoration', school: 'Abjuration', classes: ['bard', 'cleric', 'druid'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Imbue creature with positive energy. End one: reduce exhaustion by one level, charmed or petrified condition, one curse (including attunement to cursed item), any reduction to ability score, or any effect reducing HP maximum.', tags: ['healing', 'restoration'] },
    { id: 'hallow', name: 'Hallow', school: 'Evocation', classes: ['cleric'], castingTime: '24 hours', range: 'Touch', components: 'V, S, M', duration: 'Until dispelled', description: 'Touch a point to create 60-foot radius hallowed area. Celestials, elementals, fey, fiends, undead can\'t enter. Add one extra effect: Courage, Darkness, Daylight, Energy Protection, Everlasting Rest, Extradimensional Interference, Fear, Silence, or Tongues.', tags: ['protection', 'ritual'] },
    { id: 'hold-monster', name: 'Hold Monster', school: 'Enchantment', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '90 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Choose creature you can see. Wis save or be paralyzed. Target repeats save at end of each turn. Upcast: +1 target per slot level above 5th.', tags: ['control', 'debuff'] },
    { id: 'insect-plague', name: 'Insect Plague', school: 'Conjuration', classes: ['cleric', 'druid', 'sorcerer'], castingTime: '1 action', range: '300 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Swarming, biting locusts fill 20-foot radius sphere. Area is lightly obscured and difficult terrain. Creature entering or starting turn there makes Con save, taking 4d10 piercing on fail (half on success). Upcast: +1d10 per slot level above 5th.', tags: ['damage', 'control', 'aoe'] },
    { id: 'legend-lore', name: 'Legend Lore', school: 'Divination', classes: ['bard', 'cleric', 'wizard'], castingTime: '10 minutes', range: 'Self', components: 'V, S, M', duration: 'Instantaneous', description: 'Learn legendary information about a person, place, or object. If thing is of legendary importance, you learn lore. Information might include current tales, forgotten stories, or secret lore.', tags: ['utility', 'knowledge'] },
    { id: 'mass-cure-wounds', name: 'Mass Cure Wounds', school: 'Evocation', classes: ['bard', 'cleric', 'druid'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Up to 6 creatures in 30-foot radius regain 3d8 + spellcasting modifier HP. No effect on undead or constructs. Upcast: +1d8 per slot level above 5th.', tags: ['healing', 'aoe'] },
    { id: 'mislead', name: 'Mislead', school: 'Illusion', classes: ['bard', 'wizard'], castingTime: '1 action', range: 'Self', components: 'S', duration: 'Concentration, 1 hour', description: 'Become invisible and create illusory double at your location. You can see and hear through the double. Use action to move it up to twice your speed and speak through it.', tags: ['illusion', 'stealth'] },
    { id: 'modify-memory', name: 'Modify Memory', school: 'Enchantment', classes: ['bard', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Charm a creature (Wis save negates). While charmed, reshape its memories of an event within the last 24 hours (no longer than 10 minutes). Modified memory must make sense. Upcast: extends time (7 days at 6th, 30 days at 7th, 1 year at 8th, any time at 9th).', tags: ['charm', 'control'] },
    { id: 'passwall', name: 'Passwall', school: 'Transmutation', classes: ['wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: '1 hour', description: 'Create a passage through wood, plaster, or stone. The opening can be up to 5 feet wide, 8 feet tall, and 20 feet deep.', tags: ['utility'] },
    { id: 'planar-binding', name: 'Planar Binding', school: 'Abjuration', classes: ['bard', 'cleric', 'druid', 'wizard'], castingTime: '1 hour', range: '60 feet', components: 'V, S, M', duration: '24 hours', description: 'Bind a celestial, elemental, fey, or fiend. Target must be within range and stay there entire casting. Target makes Cha save; on fail, must serve you (if you speak its language). Upcast: duration increases (10 days at 6th, 30 days at 7th, 180 days at 8th, 1 year and 1 day at 9th).', tags: ['summoning', 'control'] },
    { id: 'raise-dead', name: 'Raise Dead', school: 'Necromancy', classes: ['bard', 'cleric', 'paladin'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Return dead creature to life (died within 10 days, not undead). Target returns with 1 HP. Cures poison/nonmagical diseases, but not magical diseases, curses, or similar. -4 penalty to attacks, saves, ability checks (reduces by 1 per long rest). Can\'t restore missing body parts.', tags: ['healing', 'resurrection'] },
    { id: 'reincarnate', name: 'Reincarnate', school: 'Transmutation', classes: ['druid'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Touch a dead humanoid (died within 10 days). Soul returns in a new body (roll d100 for race). New body has no memory of past life. Can speak with deceased soul to learn identity.', tags: ['healing', 'resurrection'] },
    { id: 'scrying', name: 'Scrying', school: 'Divination', classes: ['bard', 'cleric', 'druid', 'warlock', 'wizard'], castingTime: '10 minutes', range: 'Self', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'See and hear a creature on the same plane. Wis save (modified by your knowledge of target and physical connection). On fail, you can see 10-foot radius around target.', tags: ['detection', 'utility'] },
    { id: 'seeming', name: 'Seeming', school: 'Illusion', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S', duration: '8 hours', description: 'Change the appearance of any number of creatures you can see within range. Unwilling creatures can make Cha save. Can change height up to 1 foot, change body type, disguise clothing/weapons/equipment.', tags: ['illusion', 'utility'] },
    { id: 'swift-quiver', name: 'Swift Quiver', school: 'Transmutation', classes: ['ranger'], castingTime: '1 bonus action', range: 'Touch', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Transmute your quiver so it produces an endless supply of ammunition. On each turn, you can use a bonus action to make two attacks with a weapon that uses ammunition from the quiver.', tags: ['buff', 'combat'] },
    { id: 'telekinesis', name: 'Telekinesis', school: 'Transmutation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Gain ability to move or manipulate creatures or objects with your mind. Each turn, use action to: move object up to 1,000 pounds 30 feet, or exert fine control on object, or try to move a creature (opposed check, your spellcasting vs their Str).', tags: ['control', 'utility'] },
    { id: 'teleportation-circle', name: 'Teleportation Circle', school: 'Conjuration', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 minute', range: '10 feet', components: 'V, M', duration: 'Round', description: 'Draw a circle that links to another permanent teleportation circle. Any creature entering your circle is instantly transported to the destination. Casting daily for 1 year makes it permanent.', tags: ['teleportation', 'utility'] },
    { id: 'tree-stride', name: 'Tree Stride', school: 'Conjuration', classes: ['druid', 'ranger'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Gain ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Uses 5 feet of movement. Must be able to see or know location of destination tree.', tags: ['mobility', 'teleportation', 'nature'] },
    { id: 'wall-of-force', name: 'Wall of Force', school: 'Evocation', classes: ['wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Create an invisible wall of force. Can be a dome/sphere up to 10-foot radius or up to ten 10-foot panels. Nothing can physically pass through. Immune to all damage. Dispel magic can dispel it.', tags: ['protection', 'control'] },
    { id: 'wall-of-stone', name: 'Wall of Stone', school: 'Evocation', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Create a wall of nonmagical stone. Up to ten 10×10×6-inch panels. Each panel must be contiguous. If wall cuts through creature\'s space, creature is pushed to safe side (Dex save to choose). Wall can be destroyed (AC 15, 30 HP per panel).', tags: ['control', 'terrain'] },
  ],

  // 6th Level Spells (abbreviated for key spells)
  6: [
    { id: 'blade-barrier', name: 'Blade Barrier', school: 'Evocation', classes: ['cleric'], castingTime: '1 action', range: '90 feet', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Create vertical wall of blades up to 100 feet long, 20 feet high, 5 feet thick. Provides three-quarters cover. Creature passing through takes 6d10 slashing (Dex half).', tags: ['damage', 'control'] },
    { id: 'chain-lightning', name: 'Chain Lightning', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '150 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Lightning arcs from you to target, then jumps to up to 3 additional targets within 30 feet. Each target makes Dex save, taking 10d8 lightning on fail (half on success). Upcast: +1 target per slot level above 6th.', tags: ['damage', 'lightning'] },
    { id: 'circle-of-death', name: 'Circle of Death', school: 'Necromancy', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '150 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Sphere of negative energy ripples out in 60-foot radius. Creatures make Con save, taking 8d6 necrotic on fail (half on success). Upcast: +2d6 per slot level above 6th.', tags: ['damage', 'necrotic', 'aoe'] },
    { id: 'disintegrate', name: 'Disintegrate', school: 'Transmutation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Thin green ray springs from your finger. Target makes Dex save; 10d6+40 force damage on fail, nothing on success. If damage reduces target to 0 HP, it is disintegrated. Disintegrates up to 10-foot cube of nonmagical object. Upcast: +3d6 per slot level above 6th.', tags: ['damage', 'force'] },
    { id: 'eyebite', name: 'Eyebite', school: 'Necromancy', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Your eyes become void. Use action each turn to target creature within 60 feet that can see you. Choose: Asleep (Wis save or fall unconscious), Panicked (Wis save or frightened), Sickened (Con save or disadvantage on attacks/checks).', tags: ['debuff', 'control'] },
    { id: 'find-the-path', name: 'Find the Path', school: 'Divination', classes: ['bard', 'cleric', 'druid'], castingTime: '1 minute', range: 'Self', components: 'V, S, M', duration: 'Concentration, 1 day', description: 'Name a specific location. While spell lasts, you know the shortest, most direct route to that location (not necessarily safest).', tags: ['utility', 'navigation'] },
    { id: 'globe-of-invulnerability', name: 'Globe of Invulnerability', school: 'Abjuration', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self (10-foot radius)', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create immobile, faintly shimmering barrier. Any spell of 5th level or lower cast from outside can\'t affect creatures or objects within. Upcast: blocks one level higher per slot level above 6th.', tags: ['protection', 'defense'] },
    { id: 'harm', name: 'Harm', school: 'Necromancy', classes: ['cleric'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Unleash a virulent disease. Target makes Con save, taking 14d6 necrotic on fail (half on success). HP maximum is reduced by damage taken (restored by greater restoration or similar). Can\'t reduce HP below 1.', tags: ['damage', 'necrotic'] },
    { id: 'heal', name: 'Heal', school: 'Evocation', classes: ['cleric', 'druid'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Creature regains 70 HP and is cured of blindness, deafness, and any diseases. No effect on undead or constructs. Upcast: +10 HP per slot level above 6th.', tags: ['healing'] },
    { id: 'heroes-feast', name: "Heroes' Feast", school: 'Conjuration', classes: ['cleric', 'druid'], castingTime: '10 minutes', range: '30 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Create a magnificent feast for up to 12 creatures. Takes 1 hour to consume. Cures diseases/poison, grants immunity to poison/frightened, advantage on Wis saves, and 2d10 additional HP max (24 hours).', tags: ['buff', 'healing'] },
    { id: 'mass-suggestion', name: 'Mass Suggestion', school: 'Enchantment', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, M', duration: '24 hours', description: 'Suggest a course of activity to up to 12 creatures you can see that can hear and understand you. Wis save negates. Upcast: duration increases (10 days at 7th, 30 days at 8th, 1 year and 1 day at 9th).', tags: ['charm', 'control'] },
    { id: 'move-earth', name: 'Move Earth', school: 'Transmutation', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 2 hours', description: 'Reshape terrain in 40-foot square up to 10 feet deep. Move earth slowly (change happens over 10 minutes). Not violent enough to cause damage.', tags: ['utility', 'terrain'] },
    { id: 'ottos-irresistible-dance', name: "Otto's Irresistible Dance", school: 'Enchantment', classes: ['bard', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V', duration: 'Concentration, 1 minute', description: 'Target begins dancing. While dancing: must use all movement dancing in place, disadvantage on Dex saves, disadvantage on attacks against it. Target can use action to make Wis save to end effect.', tags: ['control', 'debuff'] },
    { id: 'planar-ally', name: 'Planar Ally', school: 'Conjuration', classes: ['cleric'], castingTime: '10 minutes', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Beseech an otherworldly entity for aid. Entity sends a celestial, elemental, or fiend. Creature is not under your control; you must bargain for its services.', tags: ['summoning'] },
    { id: 'sunbeam', name: 'Sunbeam', school: 'Evocation', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: 'Self (60-foot line)', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Beam of brilliant light flashes in 60-foot line, 5 feet wide. Creatures make Con save, taking 6d8 radiant on fail (half on success) and are blinded until your next turn. Undead and oozes have disadvantage. Can create new line each turn as action.', tags: ['damage', 'radiant', 'aoe'] },
    { id: 'transport-via-plants', name: 'Transport via Plants', school: 'Conjuration', classes: ['druid'], castingTime: '1 action', range: '10 feet', components: 'V, S', duration: '1 round', description: 'Create magical link between Large or larger plant and another plant on same plane. Any creature can step through and exit from destination plant.', tags: ['teleportation', 'nature'] },
    { id: 'true-seeing', name: 'True Seeing', school: 'Divination', classes: ['bard', 'cleric', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: '1 hour', description: 'Target gains truesight out to 120 feet: see in normal and magical darkness, see invisible creatures and objects, automatically detect visual illusions, see original form of shapechanger/transformed creature, see into Ethereal Plane.', tags: ['detection', 'buff'] },
    { id: 'wall-of-ice', name: 'Wall of Ice', school: 'Evocation', classes: ['wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Create ice wall. Up to ten 10-foot panels. Creature in wall\'s space makes Dex save, taking 10d6 cold on fail (half on success). Wall has AC 12, 30 HP per 10-foot section. When section is destroyed, area is difficult terrain and deals 5d6 cold (Dex half).', tags: ['damage', 'cold', 'control'] },
    { id: 'wall-of-thorns', name: 'Wall of Thorns', school: 'Conjuration', classes: ['druid'], castingTime: '1 action', range: '120 feet', components: 'V, S, M', duration: 'Concentration, 10 minutes', description: 'Create wall of tough, pliable thorns up to 60 feet long, 10 feet high, 5 feet thick. Creature entering or passing through makes Dex save, taking 7d8 slashing on fail (half on success). Upcast: +1d8 per slot level above 6th.', tags: ['damage', 'control'] },
    { id: 'word-of-recall', name: 'Word of Recall', school: 'Conjuration', classes: ['cleric'], castingTime: '1 action', range: '5 feet', components: 'V', duration: 'Instantaneous', description: 'You and up to 5 willing creatures within 5 feet are instantly transported to a previously designated sanctuary associated with your deity.', tags: ['teleportation', 'utility'] },
  ],

  // 7th-9th Level (key spells only for space)
  7: [
    { id: 'conjure-celestial', name: 'Conjure Celestial', school: 'Conjuration', classes: ['cleric'], castingTime: '1 minute', range: '90 feet', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Summon a celestial of CR 4 or lower. It is friendly and obeys your verbal commands. Upcast: CR 5 at 9th level.', tags: ['summoning'] },
    { id: 'divine-word', name: 'Divine Word', school: 'Evocation', classes: ['cleric'], castingTime: '1 bonus action', range: '30 feet', components: 'V', duration: 'Instantaneous', description: 'Utter a divine word. Creatures within range make Cha save. Effects based on current HP: 50+ deafened 1 min, 40- blinded 10 min, 30- stunned 1 hour, 20- killed. Celestials/elementals/fey/fiends failing save are forced back to home plane.', tags: ['damage', 'banishment'] },
    { id: 'etherealness', name: 'Etherealness', school: 'Transmutation', classes: ['bard', 'cleric', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S', duration: '8 hours', description: 'Step into Ethereal Plane. You can see and hear the plane you originated from (grayed out, 60-foot sight). Moving uses your normal speed. You can affect and be affected only by other creatures on Ethereal Plane. Upcast: +3 targets per slot level above 7th.', tags: ['utility', 'planar'] },
    { id: 'finger-of-death', name: 'Finger of Death', school: 'Necromancy', classes: ['sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Send negative energy coursing through a creature. Con save; 7d8+30 necrotic on fail (half on success). Humanoid killed by this spell rises as a zombie at the start of your next turn, permanently under your command.', tags: ['damage', 'necrotic', 'necromancy'] },
    { id: 'fire-storm', name: 'Fire Storm', school: 'Evocation', classes: ['cleric', 'druid', 'sorcerer'], castingTime: '1 action', range: '150 feet', components: 'V, S', duration: 'Instantaneous', description: 'Storm of roaring flame appears in up to ten 10-foot cubes (arrange as you wish). Creatures make Dex save, taking 7d10 fire on fail (half on success). Can designate creatures and objects as unaffected.', tags: ['damage', 'fire', 'aoe'] },
    { id: 'forcecage', name: 'Forcecage', school: 'Evocation', classes: ['bard', 'warlock', 'wizard'], castingTime: '1 action', range: '100 feet', components: 'V, S, M', duration: '1 hour', description: 'Create an immobile, invisible, cube-shaped prison of force. Choose: cage (barred, 10-foot cube, bars 1/2 inch apart) or box (solid walls, up to 10-foot cube). Nothing can pass through walls or teleport in/out without Cha save.', tags: ['control', 'prison'] },
    { id: 'mirage-arcane', name: 'Mirage Arcane', school: 'Illusion', classes: ['bard', 'druid', 'wizard'], castingTime: '10 minutes', range: 'Sight', components: 'V, S', duration: '10 days', description: 'Make terrain in 1-mile square look, sound, smell, and feel like other terrain. Tactile components are real enough to support weight.', tags: ['illusion', 'terrain'] },
    { id: 'plane-shift', name: 'Plane Shift', school: 'Conjuration', classes: ['cleric', 'druid', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Transport yourself and up to 8 willing creatures to a different plane. Can also banish an unwilling creature (melee spell attack, Cha save negates).', tags: ['teleportation', 'planar', 'banishment'] },
    { id: 'regenerate', name: 'Regenerate', school: 'Transmutation', classes: ['bard', 'cleric', 'druid'], castingTime: '1 minute', range: 'Touch', components: 'V, S, M', duration: '1 hour', description: 'Touch a creature. It regains 4d8+15 HP and regains 1 HP at the start of each of its turns for the duration. Severed body parts regrow after 2 minutes.', tags: ['healing'] },
    { id: 'resurrection', name: 'Resurrection', school: 'Necromancy', classes: ['bard', 'cleric'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Return a creature dead up to 100 years to life. Neutralizes poisons, cures normal diseases, but not magical diseases/curses. Restores all HP. Can restore missing body parts. Takes -4 penalty to all d20 rolls (reduces by 1 per long rest).', tags: ['healing', 'resurrection'] },
    { id: 'reverse-gravity', name: 'Reverse Gravity', school: 'Transmutation', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '100 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Reverse gravity in 50-foot-radius, 100-foot-high cylinder. Creatures and objects fall upward. Creature can make Dex save to grab fixed object. If they reach top and hit solid surface, they take falling damage. Objects and creatures fall back down when spell ends.', tags: ['control', 'utility'] },
    { id: 'sequester', name: 'Sequester', school: 'Transmutation', classes: ['wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S, M', duration: 'Until dispelled', description: 'Render a willing creature or object invisible and hidden from divination. Time stops for the target. Can set condition to end the spell.', tags: ['utility', 'protection'] },
    { id: 'simulacrum', name: 'Simulacrum', school: 'Illusion', classes: ['wizard'], castingTime: '12 hours', range: 'Touch', components: 'V, S, M', duration: 'Until dispelled', description: 'Create an illusory duplicate of a beast or humanoid. The simulacrum has half the creature\'s HP max, no equipment, and can\'t regain spell slots. It obeys your commands.', tags: ['summoning', 'illusion'] },
    { id: 'symbol', name: 'Symbol', school: 'Abjuration', classes: ['bard', 'cleric', 'wizard'], castingTime: '1 minute', range: 'Touch', components: 'V, S, M', duration: 'Until dispelled or triggered', description: 'Inscribe a harmful glyph. When triggered, affects creatures within 60 feet. Effects: Death, Discord, Fear, Hopelessness, Insanity, Pain, Sleep, or Stunning.', tags: ['trap', 'control'] },
    { id: 'teleport', name: 'Teleport', school: 'Conjuration', classes: ['bard', 'sorcerer', 'wizard'], castingTime: '1 action', range: '10 feet', components: 'V', duration: 'Instantaneous', description: 'Instantly transport yourself and up to 8 willing creatures to a destination you choose. Accuracy depends on familiarity with destination.', tags: ['teleportation'] },
  ],

  8: [
    { id: 'antimagic-field', name: 'Antimagic Field', school: 'Abjuration', classes: ['cleric', 'wizard'], castingTime: '1 action', range: 'Self (10-foot-radius sphere)', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Create 10-foot-radius sphere of antimagic. Spells can\'t be cast, magical effects are suppressed, magic items become mundane.', tags: ['protection', 'control'] },
    { id: 'clone', name: 'Clone', school: 'Necromancy', classes: ['wizard'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Grow an inert duplicate of a living creature. If original creature dies, its soul transfers to clone (if free and willing). Clone is identical to original at time of casting.', tags: ['utility', 'resurrection'] },
    { id: 'control-weather', name: 'Control Weather', school: 'Transmutation', classes: ['cleric', 'druid', 'wizard'], castingTime: '10 minutes', range: 'Self (5-mile radius)', components: 'V, S, M', duration: 'Concentration, 8 hours', description: 'Take control of the weather within 5 miles. You can change precipitation, temperature, and wind. Changes take 1d4 × 10 minutes to take effect.', tags: ['utility', 'control'] },
    { id: 'demiplane', name: 'Demiplane', school: 'Conjuration', classes: ['warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'S', duration: '1 hour', description: 'Create a door to a demiplane that appears as a 30-foot cube. Can create new or access existing demiplanes you\'ve created.', tags: ['utility', 'planar'] },
    { id: 'dominate-monster', name: 'Dominate Monster', school: 'Enchantment', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Concentration, 1 hour', description: 'Charm a creature you can see. Wis save (advantage if fighting you). Telepathic link, command as action or reaction. New save when takes damage. Upcast: 8 hours at 9th level.', tags: ['charm', 'control'] },
    { id: 'earthquake', name: 'Earthquake', school: 'Evocation', classes: ['cleric', 'druid', 'sorcerer'], castingTime: '1 action', range: '500 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Create a seismic disturbance in 100-foot-radius circle. Creatures must make Dex save each turn or fall prone. Difficult terrain. Can cause fissures, damage structures.', tags: ['control', 'damage', 'terrain'] },
    { id: 'feeblemind', name: 'Feeblemind', school: 'Enchantment', classes: ['bard', 'druid', 'warlock', 'wizard'], castingTime: '1 action', range: '150 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Blast a creature\'s mind. Int save; 4d6 psychic damage on fail and Int and Cha become 1. Can\'t cast spells, activate items, understand language, or communicate. Creature can repeat save every 30 days.', tags: ['damage', 'psychic', 'debuff'] },
    { id: 'glibness', name: 'Glibness', school: 'Transmutation', classes: ['bard', 'warlock'], castingTime: '1 action', range: 'Self', components: 'V', duration: '1 hour', description: 'Whenever you make a Charisma check, you can replace the number you roll with a 15. Magic that would determine if you\'re lying indicates you\'re being truthful.', tags: ['buff', 'social'] },
    { id: 'holy-aura', name: 'Holy Aura', school: 'Abjuration', classes: ['cleric'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Divine light shines in 30-foot radius. Creatures you choose have advantage on all saving throws, and other creatures have disadvantage on attacks against them. Fiend or undead hitting with melee must make Con save or be blinded until end of spell.', tags: ['buff', 'protection', 'aoe'] },
    { id: 'incendiary-cloud', name: 'Incendiary Cloud', school: 'Conjuration', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '150 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Swirling cloud of smoke and embers in 20-foot-radius sphere. Heavily obscures. Creatures entering or starting turn in cloud make Dex save, taking 10d8 fire on fail (half on success). Cloud moves 10 feet away from you at start of your turn.', tags: ['damage', 'fire', 'control'] },
    { id: 'maze', name: 'Maze', school: 'Conjuration', classes: ['wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Concentration, 10 minutes', description: 'Banish a creature into a labyrinthine demiplane. Creature can use action to make DC 20 Int check to escape. When spell ends, target reappears in nearest unoccupied space.', tags: ['control', 'banishment'] },
    { id: 'mind-blank', name: 'Mind Blank', school: 'Abjuration', classes: ['bard', 'wizard'], castingTime: '1 action', range: 'Touch', components: 'V, S', duration: '24 hours', description: 'Until spell ends, one willing creature is immune to psychic damage, any effect that would sense emotions/read thoughts, divination spells, and the charmed condition.', tags: ['protection', 'buff'] },
    { id: 'power-word-stun', name: 'Power Word Stun', school: 'Enchantment', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V', duration: 'Instantaneous', description: 'Speak a word of power that can overwhelm the mind of one creature. If target has 150 HP or fewer, it is stunned. Otherwise, spell has no effect. Target repeats Con save at end of each turn to end effect.', tags: ['control', 'debuff'] },
    { id: 'sunburst', name: 'Sunburst', school: 'Evocation', classes: ['druid', 'sorcerer', 'wizard'], castingTime: '1 action', range: '150 feet', components: 'V, S, M', duration: 'Instantaneous', description: 'Brilliant sunlight flashes in 60-foot radius. Creatures make Con save, taking 12d6 radiant on fail (half on success) and are blinded for 1 minute (repeat save each turn). Dispels magical darkness.', tags: ['damage', 'radiant', 'aoe'] },
    { id: 'telepathy', name: 'Telepathy', school: 'Evocation', classes: ['wizard'], castingTime: '1 action', range: 'Unlimited', components: 'V, S, M', duration: '24 hours', description: 'Create a telepathic link with one willing creature you\'re familiar with. Until spell ends, you and target can instantaneously share words, images, sounds, and other sensory messages. Works across any distance and planes.', tags: ['communication', 'utility'] },
    { id: 'tsunami', name: 'Tsunami', school: 'Conjuration', classes: ['druid'], castingTime: '1 minute', range: 'Sight', components: 'V, S', duration: 'Concentration, 6 rounds', description: 'Create a wall of water up to 300 feet long, 300 feet high, 50 feet thick. Creatures make Str save, taking 6d10 bludgeoning on fail (half on success). Wave moves 50 feet away each round. Damage decreases 1d10 each round.', tags: ['damage', 'control'] },
  ],

  9: [
    { id: 'astral-projection', name: 'Astral Projection', school: 'Necromancy', classes: ['cleric', 'warlock', 'wizard'], castingTime: '1 hour', range: '10 feet', components: 'V, S, M', duration: 'Special', description: 'Project yourself and up to 8 willing creatures into the Astral Plane. Your body remains behind in suspended animation. You can travel through the Astral Plane and to other planes.', tags: ['utility', 'planar'] },
    { id: 'foresight', name: 'Foresight', school: 'Divination', classes: ['bard', 'druid', 'warlock', 'wizard'], castingTime: '1 minute', range: 'Touch', components: 'V, S, M', duration: '8 hours', description: 'Touch a willing creature. For the duration, target can\'t be surprised, has advantage on attack rolls, ability checks, and saving throws, and other creatures have disadvantage on attacks against it.', tags: ['buff', 'protection'] },
    { id: 'gate', name: 'Gate', school: 'Conjuration', classes: ['cleric', 'sorcerer', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S, M', duration: 'Concentration, 1 minute', description: 'Conjure a portal to a specific location on a different plane. You can also speak the true name of a specific creature (not a deity) to pull them through (Cha save for unwilling).', tags: ['teleportation', 'planar', 'summoning'] },
    { id: 'imprisonment', name: 'Imprisonment', school: 'Abjuration', classes: ['warlock', 'wizard'], castingTime: '1 minute', range: '30 feet', components: 'V, S, M', duration: 'Until dispelled', description: 'Create a magical restraint. Wis save negates. Options include: Burial (entombed in stone), Chaining (bound by chains), Hedged Prison (confined to small area), Minimus Containment (shrunk into gem), Slumber (put to sleep).', tags: ['control', 'prison'] },
    { id: 'mass-heal', name: 'Mass Heal', school: 'Evocation', classes: ['cleric'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'Flood of healing energy flows from you into creatures in 60 feet. Restore up to 700 HP divided among any creatures you choose. Cures all diseases and ends blindness/deafness.', tags: ['healing', 'aoe'] },
    { id: 'meteor-swarm', name: 'Meteor Swarm', school: 'Evocation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: '1 mile', components: 'V, S', duration: 'Instantaneous', description: 'Four blazing orbs crash down at points you choose within range. Each creature in 40-foot radius sphere at each point makes Dex save, taking 20d6 fire + 20d6 bludgeoning on fail (half on success). Area becomes difficult terrain.', tags: ['damage', 'fire', 'aoe'] },
    { id: 'power-word-heal', name: 'Power Word Heal', school: 'Evocation', classes: ['bard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: 'Instantaneous', description: 'A wave of healing energy washes over one creature. Target regains all its HP. Also ends charmed, frightened, paralyzed, stunned. Target can use reaction to stand up.', tags: ['healing'] },
    { id: 'power-word-kill', name: 'Power Word Kill', school: 'Enchantment', classes: ['bard', 'sorcerer', 'warlock', 'wizard'], castingTime: '1 action', range: '60 feet', components: 'V', duration: 'Instantaneous', description: 'Utter a word of power that instantly kills one creature you can see within range if it has 100 HP or fewer.', tags: ['damage'] },
    { id: 'prismatic-wall', name: 'Prismatic Wall', school: 'Abjuration', classes: ['wizard'], castingTime: '1 action', range: '60 feet', components: 'V, S', duration: '10 minutes', description: 'Create a wall of shimmering, multicolored light up to 90 feet long, 30 feet high. Seven layers, each a different color with different effects. Must destroy layers in order to pass through.', tags: ['protection', 'control'] },
    { id: 'shapechange', name: 'Shapechange', school: 'Transmutation', classes: ['druid', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Transform into any creature with CR equal to or less than your level. You gain the creature\'s game statistics but retain your own mental ability scores, hit points, and class features. Can change form as action.', tags: ['transformation'] },
    { id: 'storm-of-vengeance', name: 'Storm of Vengeance', school: 'Conjuration', classes: ['druid'], castingTime: '1 action', range: 'Sight', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Create churning storm 360 feet across, 1 mile high. Each round, different effects occur: thunder damage, acid rain, lightning bolts, hailstones, and finally freezing rain and wind.', tags: ['damage', 'control', 'aoe'] },
    { id: 'time-stop', name: 'Time Stop', school: 'Transmutation', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V', duration: 'Instantaneous', description: 'Briefly stop the flow of time for everyone but yourself. You take 1d4+1 turns in a row. Actions that affect another creature or its equipment end the spell immediately.', tags: ['utility'] },
    { id: 'true-polymorph', name: 'True Polymorph', school: 'Transmutation', classes: ['bard', 'warlock', 'wizard'], castingTime: '1 action', range: '30 feet', components: 'V, S, M', duration: 'Concentration, 1 hour', description: 'Transform a creature into a different creature or object, or an object into a creature. Wis save for unwilling. If you concentrate for the full duration, transformation becomes permanent.', tags: ['transformation'] },
    { id: 'true-resurrection', name: 'True Resurrection', school: 'Necromancy', classes: ['cleric', 'druid'], castingTime: '1 hour', range: 'Touch', components: 'V, S, M', duration: 'Instantaneous', description: 'Return to life a creature that has died within the last 200 years. Provides a new body if original was destroyed. Restores all HP, neutralizes poisons, cures diseases, ends curses, restores any missing parts.', tags: ['healing', 'resurrection'] },
    { id: 'weird', name: 'Weird', school: 'Illusion', classes: ['wizard'], castingTime: '1 action', range: '120 feet', components: 'V, S', duration: 'Concentration, 1 minute', description: 'Draw on the deepest fears of creatures within 30-foot radius sphere. Each creature makes Wis save or become frightened. Frightened creature takes 4d10 psychic damage at start of each turn. Repeat save at end of each turn.', tags: ['damage', 'psychic', 'fear', 'illusion'] },
    { id: 'wish', name: 'Wish', school: 'Conjuration', classes: ['sorcerer', 'wizard'], castingTime: '1 action', range: 'Self', components: 'V', duration: 'Instantaneous', description: 'The mightiest spell a mortal can cast. Can duplicate any spell of 8th level or lower, create objects worth up to 25,000 gp, grant resistance to a damage type, or state any other wish (GM determines outcome). Stress may prevent casting wish again.', tags: ['utility'] },
  ],

  // Helper methods
  getSpellsByLevel(level) {
    return this[level] || [];
  },

  getSpellsByClassAndLevel(classId, level) {
    const normalizedClass = classId.toLowerCase();
    return (this[level] || []).filter(spell => 
      spell.classes.includes(normalizedClass)
    );
  },

  getSpellsForClass(classId, maxLevel = 9) {
    const normalizedClass = classId.toLowerCase();
    const result = { cantrips: [], spells: {} };
    
    // Get cantrips
    result.cantrips = (this[0] || []).filter(spell => 
      spell.classes.includes(normalizedClass)
    );
    
    // Get spells by level
    for (let level = 1; level <= maxLevel; level++) {
      const levelSpells = (this[level] || []).filter(spell => 
        spell.classes.includes(normalizedClass)
      );
      if (levelSpells.length > 0) {
        result.spells[level] = levelSpells;
      }
    }
    
    return result;
  },

  getSpellByName(name) {
    const normalizedName = name.toLowerCase().trim();
    for (let level = 0; level <= 9; level++) {
      const spells = this[level] || [];
      const found = spells.find(spell => 
        spell.name.toLowerCase() === normalizedName || 
        spell.id === normalizedName
      );
      if (found) return { ...found, level };
    }
    return null;
  },

  searchSpells(query, filters = {}) {
    const normalizedQuery = query.toLowerCase().trim();
    const results = [];
    
    const minLevel = filters.minLevel ?? 0;
    const maxLevel = filters.maxLevel ?? 9;
    const classFilter = filters.class?.toLowerCase();
    const schoolFilter = filters.school?.toLowerCase();
    const tagFilter = filters.tag?.toLowerCase();
    
    for (let level = minLevel; level <= maxLevel; level++) {
      const spells = this[level] || [];
      for (const spell of spells) {
        // Match query against name or description
        const matchesQuery = !normalizedQuery || 
          spell.name.toLowerCase().includes(normalizedQuery) ||
          spell.description.toLowerCase().includes(normalizedQuery);
        
        // Match class filter
        const matchesClass = !classFilter || 
          spell.classes.includes(classFilter);
        
        // Match school filter
        const matchesSchool = !schoolFilter || 
          spell.school.toLowerCase() === schoolFilter;
        
        // Match tag filter
        const matchesTag = !tagFilter || 
          spell.tags.includes(tagFilter);
        
        if (matchesQuery && matchesClass && matchesSchool && matchesTag) {
          results.push({ ...spell, level });
        }
      }
    }
    
    return results;
  },

  getAllSchools() {
    const schools = new Set();
    for (let level = 0; level <= 9; level++) {
      for (const spell of this[level] || []) {
        schools.add(spell.school);
      }
    }
    return Array.from(schools).sort();
  },

  getAllTags() {
    const tags = new Set();
    for (let level = 0; level <= 9; level++) {
      for (const spell of this[level] || []) {
        spell.tags.forEach(tag => tags.add(tag));
      }
    }
    return Array.from(tags).sort();
  },
};




